) VALUES (
  'lGqSIhpx43WzvxCGjjqk',
  '20-87-CGjjqk',
  'चौथे टी-20 में न्यूजीलैंड की धमाकेदार जीत, भारत को 87 रन से हराया',
  'ऑकलैंड&nbsp;|&nbsp;30&nbsp;अक्टूबर&nbsp;2026 ऑकलैंड&nbsp;में&nbsp;खेले&nbsp;गए&nbsp;चौथे&nbsp;टी-20&nbsp;मुकाबले&nbsp;में&nbsp;न्यूजीलैंड&nbsp;ने&nbsp;भारतीय&nbsp;टीम&nbsp;को&nbsp;87&nbsp;रन&nbsp;से&n...',
  '<p><strong>ऑकलैंड&nbsp;|&nbsp;30&nbsp;अक्टूबर&nbsp;2026</strong></p><p></p><p>ऑकलैंड&nbsp;में&nbsp;खेले&nbsp;गए&nbsp;चौथे&nbsp;टी-20&nbsp;मुकाबले&nbsp;में&nbsp;न्यूजीलैंड&nbsp;ने&nbsp;भारतीय&nbsp;टीम&nbsp;को&nbsp;87&nbsp;रन&nbsp;से&nbsp;करारी&nbsp;शिकस्त&nbsp;दी।&nbsp;न्यूजीलैंड&nbsp;ने&nbsp;पहले&nbsp;बल्लेबाजी&nbsp;करते&nbsp;हुए&nbsp;निर्धारित&nbsp;20&nbsp;ओवर&nbsp;में&nbsp;7&nbsp;विकेट&nbsp;के&nbsp;नुकसान&nbsp;पर&nbsp;259&nbsp;रन&nbsp;का&nbsp;विशाल&nbsp;स्कोर&nbsp;खड़ा&nbsp;किया।&nbsp;जवाब&nbsp;में&nbsp;भारतीय&nbsp;टीम&nbsp;20&nbsp;ओवर&nbsp;में&nbsp;9&nbsp;विकेट&nbsp;खोकर&nbsp;172&nbsp;रन&nbsp;ही&nbsp;बना&nbsp;सकी।</p><p></p><p>ग्लेन&nbsp;फिलिप्स&nbsp;का&nbsp;शतक,&nbsp;न्यूजीलैंड&nbsp;ने&nbsp;बनाया&nbsp;विशाल&nbsp;स्कोर</p><p></p><p>न्यूजीलैंड&nbsp;की&nbsp;ओर&nbsp;से&nbsp;ग्लेन&nbsp;फिलिप्स&nbsp;ने&nbsp;विस्फोटक&nbsp;बल्लेबाजी&nbsp;करते&nbsp;हुए&nbsp;49&nbsp;गेंदों&nbsp;पर&nbsp;107&nbsp;रन&nbsp;की&nbsp;शानदार&nbsp;पारी&nbsp;खेली।&nbsp;उनकी&nbsp;बल्लेबाजी&nbsp;ने&nbsp;भारतीय&nbsp;गेंदबाजों&nbsp;पर&nbsp;दबाव&nbsp;बना&nbsp;दिया।&nbsp;माइकल&nbsp;ब्रेसवेल&nbsp;ने&nbsp;भी&nbsp;आक्रामक&nbsp;अंदाज&nbsp;में&nbsp;रन&nbsp;बनाकर&nbsp;न्यूजीलैंड&nbsp;के&nbsp;स्कोर&nbsp;को&nbsp;259&nbsp;तक&nbsp;पहुंचाने&nbsp;में&nbsp;अहम&nbsp;योगदान&nbsp;दिया।</p><p></p><p>भारत&nbsp;की&nbsp;ओर&nbsp;से&nbsp;मयंक&nbsp;यादव&nbsp;ने&nbsp;शानदार&nbsp;गेंदबाजी&nbsp;करते&nbsp;हुए&nbsp;तीन&nbsp;विकेट&nbsp;हासिल&nbsp;किए।&nbsp;इसके&nbsp;बावजूद&nbsp;भारतीय&nbsp;गेंदबाज&nbsp;न्यूजीलैंड&nbsp;के&nbsp;बल्लेबाजों&nbsp;को&nbsp;बड़े&nbsp;स्कोर&nbsp;तक&nbsp;पहुंचने&nbsp;से&nbsp;नहीं&nbsp;रोक&nbsp;सके।</p><p></p><p>भारतीय&nbsp;बल्लेबाजी&nbsp;लड़खड़ाई</p><p></p><p>260&nbsp;रन&nbsp;के&nbsp;लक्ष्य&nbsp;का&nbsp;पीछा&nbsp;करने&nbsp;उतरी&nbsp;भारतीय&nbsp;टीम&nbsp;की&nbsp;शुरुआत&nbsp;बेहद&nbsp;खराब&nbsp;रही।&nbsp;जैकब&nbsp;डफी&nbsp;ने&nbsp;शुरुआती&nbsp;ओवर&nbsp;में&nbsp;संजू&nbsp;सैमसन&nbsp;और&nbsp;ईशान&nbsp;किशन&nbsp;को&nbsp;आउट&nbsp;कर&nbsp;भारत&nbsp;को&nbsp;बड़ा&nbsp;झटका&nbsp;दिया।&nbsp;इसके&nbsp;बाद&nbsp;भारतीय&nbsp;बल्लेबाज&nbsp;लगातार&nbsp;विकेट&nbsp;गंवाते&nbsp;रहे।</p><p></p><p>शुभमन&nbsp;शर्मा,&nbsp;श्रेयस&nbsp;अय्यर&nbsp;और&nbsp;अन्य&nbsp;बल्लेबाज&nbsp;बड़ी&nbsp;पारी&nbsp;खेलने&nbsp;में&nbsp;नाकाम&nbsp;रहे।&nbsp;तिलक&nbsp;वर्मा&nbsp;ने&nbsp;35&nbsp;रन&nbsp;बनाकर&nbsp;संघर्ष&nbsp;जरूर&nbsp;किया,&nbsp;लेकिन&nbsp;उन्हें&nbsp;दूसरे&nbsp;छोर&nbsp;से&nbsp;पर्याप्त&nbsp;सहयोग&nbsp;नहीं&nbsp;मिला।&nbsp;न्यूजीलैंड&nbsp;की&nbsp;ओर&nbsp;से&nbsp;जैकब&nbsp;डफी&nbsp;ने&nbsp;चार&nbsp;विकेट&nbsp;लेकर&nbsp;भारतीय&nbsp;बल्लेबाजी&nbsp;की&nbsp;कमर&nbsp;तोड़&nbsp;दी।</p><p></p><p>सीरीज&nbsp;में&nbsp;भारत&nbsp;की&nbsp;बढ़त&nbsp;बरकरार</p><p></p><p>चौथे&nbsp;टी-20&nbsp;में&nbsp;हार&nbsp;के&nbsp;बावजूद&nbsp;भारतीय&nbsp;टीम&nbsp;पांच&nbsp;मैचों&nbsp;की&nbsp;सीरीज&nbsp;में&nbsp;पहले&nbsp;ही&nbsp;अजेय&nbsp;बढ़त&nbsp;हासिल&nbsp;कर&nbsp;चुकी&nbsp;थी।&nbsp;न्यूजीलैंड&nbsp;की&nbsp;इस&nbsp;जीत&nbsp;से&nbsp;सीरीज&nbsp;के&nbsp;अंतिम&nbsp;मुकाबले&nbsp;से&nbsp;पहले&nbsp;मेजबान&nbsp;टीम&nbsp;का&nbsp;मनोबल&nbsp;जरूर&nbsp;बढ़ेगा।</p><p></p><p>अब&nbsp;सभी&nbsp;की&nbsp;निगाहें&nbsp;रविवार&nbsp;को&nbsp;खेले&nbsp;जाने&nbsp;वाले&nbsp;पांचवें&nbsp;और&nbsp;अंतिम&nbsp;टी-20&nbsp;मुकाबले&nbsp;पर&nbsp;होंगी,&nbsp;जहां&nbsp;भारतीय&nbsp;टीम&nbsp;जीत&nbsp;के&nbsp;साथ&nbsp;सीरीज&nbsp;का&nbsp;समापन&nbsp;करना&nbsp;चाहेगी।</p>',
  'Sports',
  '["#breaking","#sports","#exclusive"]',
  '',
  '',
  '[]',
  'https://media.currentnews.blog/uploads/photo.jpg/img/lGqSIhpx43WzvxCGjjqk-1.webp',
  'https://media.currentnews.blog/uploads/photo.jpg/img/lGqSIhpx43WzvxCGjjqk-2.webp',
  '["https://media.currentnews.blog/uploads/photo.jpg/img/lGqSIhpx43WzvxCGjjqk-3.webp"]',
  '["https://media.currentnews.blog/uploads/photo.jpg/img/lGqSIhpx43WzvxCGjjqk-4.webp"]',
  'middle',
  '[]',
  'Current News',
  1793375719856,
