) VALUES (
  'Mb0SKs2bF11I7JvCu2HJ',
  '3-0-vCu2HJ',
  'अभिषेक शर्मा के तूफानी शतक से भारत की धमाकेदार जीत, न्यूजीलैंड को 3-0 से पछाड़ा',
  'अभिषेक&nbsp;शर्मा&nbsp;के&nbsp;तूफानी&nbsp;शतक&nbsp;से&nbsp;भारत&nbsp;की&nbsp;धमाकेदार&nbsp;जीत,&nbsp;न्यूजीलैंड&nbsp;को&nbsp;3-0&nbsp;से&nbsp;पछाड़ा वेलिंगटन,&nbsp;27&nbsp;अक्टूबर।&nbsp;भारतीय&nbsp;क...',
  '<p>अभिषेक&nbsp;शर्मा&nbsp;के&nbsp;तूफानी&nbsp;शतक&nbsp;से&nbsp;भारत&nbsp;की&nbsp;धमाकेदार&nbsp;जीत,&nbsp;न्यूजीलैंड&nbsp;को&nbsp;3-0&nbsp;से&nbsp;पछाड़ा</p><p>वेलिंगटन,&nbsp;27&nbsp;अक्टूबर।&nbsp;भारतीय&nbsp;क्रिकेट&nbsp;टीम&nbsp;ने&nbsp;न्यूजीलैंड&nbsp;के&nbsp;खिलाफ&nbsp;तीसरे&nbsp;टी-20&nbsp;अंतरराष्ट्रीय&nbsp;मुकाबले&nbsp;में&nbsp;शानदार&nbsp;प्रदर्शन&nbsp;करते&nbsp;हुए&nbsp;सात&nbsp;विकेट&nbsp;से&nbsp;धमाकेदार&nbsp;जीत&nbsp;दर्ज&nbsp;की।&nbsp;इस&nbsp;जीत&nbsp;के&nbsp;साथ&nbsp;ही&nbsp;भारत&nbsp;ने&nbsp;पांच&nbsp;मैचों&nbsp;की&nbsp;टी-20&nbsp;सीरीज&nbsp;में&nbsp;3-0&nbsp;की&nbsp;अजेय&nbsp;बढ़त&nbsp;बना&nbsp;ली&nbsp;है।&nbsp;भारतीय&nbsp;टीम&nbsp;की&nbsp;इस&nbsp;ऐतिहासिक&nbsp;जीत&nbsp;के&nbsp;सबसे&nbsp;बड़े&nbsp;नायक&nbsp;युवा&nbsp;बल्लेबाज&nbsp;अभिषेक&nbsp;शर्मा&nbsp;रहे,&nbsp;जिन्होंने&nbsp;महज&nbsp;38&nbsp;गेंदों&nbsp;पर&nbsp;113&nbsp;रनों&nbsp;की&nbsp;विस्फोटक&nbsp;पारी&nbsp;खेली।</p><p>मुकाबले&nbsp;में&nbsp;पहले&nbsp;बल्लेबाजी&nbsp;करते&nbsp;हुए&nbsp;न्यूजीलैंड&nbsp;ने&nbsp;निर्धारित&nbsp;20&nbsp;ओवर&nbsp;में&nbsp;तीन&nbsp;विकेट&nbsp;के&nbsp;नुकसान&nbsp;पर&nbsp;198&nbsp;रन&nbsp;बनाए।&nbsp;न्यूजीलैंड&nbsp;की&nbsp;ओर&nbsp;से&nbsp;डेरिल&nbsp;मिचेल&nbsp;ने&nbsp;52&nbsp;गेंदों&nbsp;पर&nbsp;नाबाद&nbsp;89&nbsp;रन&nbsp;बनाए,&nbsp;जबकि&nbsp;फिन&nbsp;एलन&nbsp;ने&nbsp;40&nbsp;और&nbsp;बेवन&nbsp;जैकब्स&nbsp;ने&nbsp;नाबाद&nbsp;39&nbsp;रनों&nbsp;का&nbsp;योगदान&nbsp;दिया।</p><p>199&nbsp;रनों&nbsp;के&nbsp;लक्ष्य&nbsp;का&nbsp;पीछा&nbsp;करने&nbsp;उतरी&nbsp;भारतीय&nbsp;टीम&nbsp;ने&nbsp;शुरुआत&nbsp;से&nbsp;ही&nbsp;आक्रामक&nbsp;रुख&nbsp;अपनाया।&nbsp;अभिषेक&nbsp;शर्मा&nbsp;और&nbsp;वैभव&nbsp;सूर्यवंशी&nbsp;ने&nbsp;न्यूजीलैंड&nbsp;के&nbsp;गेंदबाजों&nbsp;की&nbsp;जमकर&nbsp;खबर&nbsp;ली।&nbsp;दोनों&nbsp;बल्लेबाजों&nbsp;ने&nbsp;पहले&nbsp;विकेट&nbsp;के&nbsp;लिए&nbsp;महज&nbsp;43&nbsp;गेंदों&nbsp;पर&nbsp;133&nbsp;रनों&nbsp;की&nbsp;साझेदारी&nbsp;कर&nbsp;मैच&nbsp;को&nbsp;एकतरफा&nbsp;बना&nbsp;दिया।</p><p>अभिषेक&nbsp;शर्मा&nbsp;ने&nbsp;अपनी&nbsp;पारी&nbsp;में&nbsp;11&nbsp;छक्के&nbsp;और&nbsp;9&nbsp;चौके&nbsp;लगाए।&nbsp;वहीं,&nbsp;वैभव&nbsp;सूर्यवंशी&nbsp;ने&nbsp;केवल&nbsp;19&nbsp;गेंदों&nbsp;पर&nbsp;45&nbsp;रनों&nbsp;की&nbsp;तेजतर्रार&nbsp;पारी&nbsp;खेली।</p><p>भारतीय&nbsp;टीम&nbsp;ने&nbsp;महज&nbsp;13.2&nbsp;ओवर&nbsp;में&nbsp;चार&nbsp;विकेट&nbsp;खोकर&nbsp;199&nbsp;रन&nbsp;बनाते&nbsp;हुए&nbsp;लक्ष्य&nbsp;हासिल&nbsp;कर&nbsp;लिया।&nbsp;इस&nbsp;जीत&nbsp;के&nbsp;साथ&nbsp;भारत&nbsp;ने&nbsp;सीरीज&nbsp;में&nbsp;3-0&nbsp;की&nbsp;निर्णायक&nbsp;बढ़त&nbsp;हासिल&nbsp;कर&nbsp;ली।</p>',
