) VALUES (
  'Z9qSPadOxSBhn2Wjyoet',
  '2-4-Wjyoet',
  'गोड्डा के जता  टोली में 2 नवंबर से शुरू होगा भागलपुर जोन का तीन दिवसीय इज्तिमा, तैयारियां अंतिम चरण में4',
  '4&nbsp;नवंबर&nbsp;को&nbsp;विशेष&nbsp;सामूहिक&nbsp;दुआ&nbsp;के&nbsp;साथ&nbsp;होगा&nbsp;समापन;&nbsp;हजारों&nbsp;अकीदतमंदों&nbsp;के&nbsp;पहुंचने&nbsp;की&nbsp;उम्मीद गोड्डा&nbsp;|&nbsp;निज&nbsp;संवाददाता...',
  '<p class="ql-align-center"><em style="text-align: left; font-size: 1rem; background-color: inherit; color: rgb(31, 31, 31);">4&nbsp;नवंबर&nbsp;को&nbsp;विशेष&nbsp;सामूहिक&nbsp;दुआ&nbsp;के&nbsp;साथ&nbsp;होगा&nbsp;समापन;&nbsp;हजारों&nbsp;अकीदतमंदों&nbsp;के&nbsp;पहुंचने&nbsp;की&nbsp;उम्मीद</em></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">गोड्डा&nbsp;|&nbsp;निज&nbsp;संवाददाता</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;गोड्डा&nbsp;जिले&nbsp;के&nbsp;जता&nbsp;टोली&nbsp;(जन्नत&nbsp;टोली)&nbsp;में&nbsp;आगामी&nbsp;2&nbsp;नवंबर&nbsp;2026&nbsp;से&nbsp;भागलपुर&nbsp;जोन&nbsp;का&nbsp;तीन&nbsp;दिवसीय&nbsp;भव्य&nbsp;धार्मिक&nbsp;इज्तिमा&nbsp;शुरू&nbsp;होने&nbsp;जा&nbsp;रहा&nbsp;है।&nbsp;2,&nbsp;3&nbsp;और&nbsp;4&nbsp;नवंबर&nbsp;तक&nbsp;चलने&nbsp;वाले&nbsp;इस&nbsp;आयोजन&nbsp;को&nbsp;लेकर&nbsp;इलाके&nbsp;में&nbsp;खासा&nbsp;उत्साह&nbsp;देखा&nbsp;जा&nbsp;रहा&nbsp;है&nbsp;और&nbsp;आयोजन&nbsp;स्थल&nbsp;पर&nbsp;तैयारियां&nbsp;लगभग&nbsp;पूरी&nbsp;कर&nbsp;ली&nbsp;गई&nbsp;हैं।</span></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">आयोजन&nbsp;समिति&nbsp;से&nbsp;मिली&nbsp;जानकारी&nbsp;के&nbsp;अनुसार,&nbsp;इज्तिमा&nbsp;का&nbsp;विधिवत&nbsp;आगाज&nbsp;2&nbsp;नवंबर&nbsp;की&nbsp;सुबह&nbsp;से&nbsp;होगा।&nbsp;तीन&nbsp;दिनों&nbsp;तक&nbsp;चलने&nbsp;वाले&nbsp;इस&nbsp;धार्मिक&nbsp;जुटान&nbsp;में&nbsp;उलेमाओं&nbsp;और&nbsp;धर्मगुरुओं&nbsp;द्वारा&nbsp;दीन,&nbsp;ईमान,&nbsp;अमन-चैन&nbsp;और&nbsp;इंसानियत&nbsp;की&nbsp;राह&nbsp;पर&nbsp;चलने&nbsp;को&nbsp;लेकर&nbsp;तकरीरें&nbsp;(प्रवचन)&nbsp;दी&nbsp;जाएंगी।&nbsp;आयोजन&nbsp;के&nbsp;तीसरे&nbsp;और&nbsp;अंतिम&nbsp;दिन,&nbsp;यानी&nbsp;4&nbsp;नवंबर&nbsp;को&nbsp;देश-दुनिया&nbsp;में&nbsp;अमन,&nbsp;भाईचारे&nbsp;और&nbsp;तरक्की&nbsp;के&nbsp;लिए&nbsp;होने&nbsp;वाली&nbsp;विशेष&nbsp;सामूहिक&nbsp;दुआ&nbsp;के&nbsp;साथ&nbsp;इस&nbsp;इज्तिमा&nbsp;का&nbsp;समापन&nbsp;किया&nbsp;जाएगा।</span><img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/Z9qSPadOxSBhn2Wjyoet-1.webp"></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">तैयारियों&nbsp;का&nbsp;जायजा:&nbsp;मुख्य&nbsp;कार्य&nbsp;पूरे,&nbsp;अंतिम&nbsp;रूप&nbsp;देने&nbsp;में&nbsp;जुटी&nbsp;टीम</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;इस&nbsp;बड़े&nbsp;आयोजन&nbsp;में&nbsp;भागलपुर&nbsp;जोन&nbsp;के&nbsp;विभिन्न&nbsp;जिलों&nbsp;से&nbsp;बड़ी&nbsp;संख्या&nbsp;में&nbsp;लोगों&nbsp;के&nbsp;शामिल&nbsp;होने&nbsp;की&nbsp;संभावना&nbsp;है।&nbsp;भीड़&nbsp;को&nbsp;देखते&nbsp;हुए&nbsp;आयोजन&nbsp;स्थल&nbsp;पर&nbsp;पंडाल,&nbsp;ठहरने,&nbsp;वजूखाने,&nbsp;पेयजल,&nbsp;साफ-सफाई&nbsp;और&nbsp;रोशनी&nbsp;जैसी&nbsp;बुनियादी&nbsp;व्यवस्थाओं&nbsp;के&nbsp;प्रमुख&nbsp;काम&nbsp;पूरे&nbsp;हो&nbsp;चुके&nbsp;हैं।&nbsp;जो&nbsp;थोड़े-बहुत&nbsp;कार्य&nbsp;शेष&nbsp;रह&nbsp;गए&nbsp;हैं,&nbsp;उन्हें&nbsp;2&nbsp;नवंबर&nbsp;से&nbsp;पहले&nbsp;समय&nbsp;पर&nbsp;पूरा&nbsp;करने&nbsp;के&nbsp;लिए&nbsp;कार्यकर्ता&nbsp;और&nbsp;स्थानीय&nbsp;लोग&nbsp;दिन-रात&nbsp;जुटे&nbsp;हुए&nbsp;हैं&nbsp;ताकि&nbsp;बाहर&nbsp;से&nbsp;आने&nbsp;वाले&nbsp;जायरीनों&nbsp;को&nbsp;किसी&nbsp;प्रकार&nbsp;की&nbsp;असुविधा&nbsp;न&nbsp;हो।</span><img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/Z9qSPadOxSBhn2Wjyoet-2.webp"></p><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">आयोजन:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;भागलपुर&nbsp;जोन&nbsp;का&nbsp;तीन&nbsp;दिवसीय&nbsp;इज्तिमा</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">स्थान:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;जता&nbsp;टोला&nbsp;,&nbsp;जिला&nbsp;गोड्डा</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">तिथि:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;2,&nbsp;3&nbsp;और&nbsp;4&nbsp;नवंबर&nbsp;2026</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">समापन:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;4&nbsp;नवंबर&nbsp;2026&nbsp;को&nbsp;विशेष&nbsp;दुआ&nbsp;के&nbsp;साथ</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">वर्तमान&nbsp;स्थिति:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;मुख्य&nbsp;तैयारियां&nbsp;पूरी,&nbsp;शेष&nbsp;कार्यों&nbsp;को&nbsp;दिया&nbsp;जा&nbsp;रहा&nbsp;अंतिम&nbsp;रूप</span></li></ul><p></p>',
  'General',
