) VALUES (
  'DK6GR9O1smRAHbs7sIcr',
  'DK6GR9O1smRAHbs7sIcr-s7sIcr',
  'गोड्डा: बाघाकोल में चोरी से हड़कंप, होंडा शोरूम के बगल के घर को बनाया निशाना',
  '​बाघाकोल,&nbsp;गोड्डा ​ब्यूरो&nbsp;/&nbsp;संवाददाता ​गोड्डा।&nbsp;मुफस्सिल&nbsp;थाना&nbsp;क्षेत्र&nbsp;अंतर्गत&nbsp;बाघाकोल&nbsp;गांव&nbsp;में&nbsp;होंडा&nbsp;शोरूम&nbsp;के&nbsp;समीप&nbsp;स्थित&nbsp;ए...',
  '<p></p><p>​बाघाकोल,&nbsp;गोड्डा<img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/DK6GR9O1smRAHbs7sIcr-1.webp"></p><p>​ब्यूरो&nbsp;/&nbsp;संवाददाता</p><p>​गोड्डा।&nbsp;मुफस्सिल&nbsp;थाना&nbsp;क्षेत्र&nbsp;अंतर्गत&nbsp;बाघाकोल&nbsp;गांव&nbsp;में&nbsp;होंडा&nbsp;शोरूम&nbsp;के&nbsp;समीप&nbsp;स्थित&nbsp;एक&nbsp;रिहायशी&nbsp;मकान&nbsp;को&nbsp;निशाना&nbsp;बनाते&nbsp;हुए&nbsp;अज्ञात&nbsp;चोरों&nbsp;ने&nbsp;सुबह&nbsp;के&nbsp;समय&nbsp;ही&nbsp;चोरी&nbsp;की&nbsp;बड़ी&nbsp;वारदात&nbsp;को&nbsp;अंजाम&nbsp;दिया।&nbsp;चोरों&nbsp;ने&nbsp;घर&nbsp;में&nbsp;रखे&nbsp;लगभग&nbsp;डेढ़&nbsp;लाख&nbsp;रुपये&nbsp;मूल्य&nbsp;के&nbsp;सोने-चांदी&nbsp;के&nbsp;जेवरातों&nbsp;पर&nbsp;हाथ&nbsp;साफ&nbsp;कर&nbsp;दिया&nbsp;और&nbsp;मौके&nbsp;से&nbsp;फरार&nbsp;हो&nbsp;गए।</p><p>​प्राप्त&nbsp;जानकारी&nbsp;के&nbsp;अनुसार,&nbsp;घटना&nbsp;सुबह&nbsp;करीब&nbsp;7:00&nbsp;बजे&nbsp;की&nbsp;बताई&nbsp;जा&nbsp;रही&nbsp;है।&nbsp;सुबह-सुबह&nbsp;हुई&nbsp;इस&nbsp;वारदात&nbsp;से&nbsp;न&nbsp;सिर्फ&nbsp;पीड़ित&nbsp;परिवार&nbsp;सदमे&nbsp;में&nbsp;है,&nbsp;बल्कि&nbsp;मुख्य&nbsp;सड़क&nbsp;और&nbsp;व्यावसायिक&nbsp;प्रतिष्ठानों&nbsp;के&nbsp;नजदीक&nbsp;स्थित&nbsp;इस&nbsp;इलाके&nbsp;में&nbsp;सुरक्षा&nbsp;को&nbsp;लेकर&nbsp;स्थानीय&nbsp;लोगों&nbsp;के&nbsp;बीच&nbsp;गहरा&nbsp;रोष&nbsp;और&nbsp;चिंता&nbsp;व्याप्त&nbsp;है।</p><p>​डेढ़&nbsp;लाख&nbsp;के&nbsp;गहने&nbsp;गायब,&nbsp;छानबीन&nbsp;शुरू</p><p>परिजनों&nbsp;के&nbsp;प्रारंभिक&nbsp;आकलन&nbsp;के&nbsp;अनुसार,&nbsp;चोरी&nbsp;गए&nbsp;सोने&nbsp;और&nbsp;चांदी&nbsp;के&nbsp;आभूषणों&nbsp;की&nbsp;अनुमानित&nbsp;कीमत&nbsp;करीब&nbsp;1.5&nbsp;लाख&nbsp;रुपये&nbsp;है।&nbsp;सुबह&nbsp;के&nbsp;वक्त&nbsp;चहल-पहल&nbsp;शुरू&nbsp;होने&nbsp;के&nbsp;दौरान&nbsp;चोरों&nbsp;द्वारा&nbsp;इतनी&nbsp;सफाई&nbsp;से&nbsp;वारदात&nbsp;को&nbsp;अंजाम&nbsp;दिए&nbsp;जाने&nbsp;की&nbsp;सूचना&nbsp;के&nbsp;बाद&nbsp;पुलिस&nbsp;भी&nbsp;मामले&nbsp;की&nbsp;छानबीन&nbsp;में&nbsp;जुट&nbsp;गई&nbsp;है।&nbsp;पुलिस&nbsp;आसपास&nbsp;लगे&nbsp;सीसीटीवी&nbsp;कैमरों&nbsp;और&nbsp;संदिग्ध&nbsp;गतिविधियों&nbsp;के&nbsp;आधार&nbsp;पर&nbsp;चोरों&nbsp;का&nbsp;सुराग&nbsp;लगाने&nbsp;का&nbsp;प्रयास&nbsp;कर&nbsp;रही&nbsp;है।</p><p></p>',
  'General',
  '["#BreakingNews","#LatestNews","#HindiNews","#GoddaPolice","#BasantraiNews"]',
  'https://youtu.be/8mMPkHvZqeM?si=17bqKRWCaEcyvcTh',
