) VALUES (
  'JyZmaVUmF1S446juFUWY',
  'fwice-juFUWY',
  'अभिनेता टाइगर श्रॉफ की कार पर जुहू में ताबड़तोड़ फायरिंग, हाथ झुलसा; FWICE ने की सुरक्षा की मांग',
  'उपमुख्यमंत्री&nbsp;एकनाथ&nbsp;शिंदे&nbsp;ने&nbsp;घर&nbsp;जाकर&nbsp;लिया&nbsp;हालचाल दोनों&nbsp;संदिग्ध&nbsp;हमलावरों&nbsp;की&nbsp;पहली&nbsp;तस्वीर&nbsp;आई&nbsp;सामने मुंबई&nbsp;(विशेष&nbsp;संवाददाता):...',
  '<h1><img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/JyZmaVUmF1S446juFUWY-1.webp"><em style="font-size: 1rem; background-color: inherit; color: rgb(31, 31, 31);">उपमुख्यमंत्री&nbsp;एकनाथ&nbsp;शिंदे&nbsp;ने&nbsp;घर&nbsp;जाकर&nbsp;लिया&nbsp;हालचाल</em></h1><p><em style="background-color: inherit; color: rgb(31, 31, 31);">दोनों&nbsp;संदिग्ध&nbsp;हमलावरों&nbsp;की&nbsp;पहली&nbsp;तस्वीर&nbsp;आई&nbsp;सामने</em></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">मुंबई&nbsp;(विशेष&nbsp;संवाददाता):</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;बॉलीवुड&nbsp;अभिनेता&nbsp;टाइगर&nbsp;श्रॉफ&nbsp;पर&nbsp;रविवार&nbsp;शाम&nbsp;उपनगरीय&nbsp;मुंबई&nbsp;के&nbsp;जुहू&nbsp;इलाके&nbsp;में&nbsp;अज्ञात&nbsp;हमलावरों&nbsp;ने&nbsp;उस&nbsp;वक्त&nbsp;फायरिंग&nbsp;कर&nbsp;दी,&nbsp;जब&nbsp;वे&nbsp;अपनी&nbsp;गाड़ी&nbsp;में&nbsp;सवार&nbsp;थे।&nbsp;इस&nbsp;जानलेवा&nbsp;हमले&nbsp;में&nbsp;टाइगर&nbsp;बाल-बाल&nbsp;बचे,&nbsp;हालांकि&nbsp;गोलीबारी&nbsp;के&nbsp;दौरान&nbsp;बारूद&nbsp;की&nbsp;आंच&nbsp;(गनपाउडर&nbsp;बर्न)&nbsp;से&nbsp;उनके&nbsp;हाथ&nbsp;में&nbsp;चोट&nbsp;आई&nbsp;है।&nbsp;घटना&nbsp;के&nbsp;बाद&nbsp;पूरे&nbsp;फिल्म&nbsp;जगत&nbsp;में&nbsp;हड़कंप&nbsp;मच&nbsp;गया&nbsp;है।</span></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">हमलावरों&nbsp;की&nbsp;तस्वीरें&nbsp;सामने&nbsp;आईं</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">जांच&nbsp;एजेंसियों&nbsp;के&nbsp;हाथ&nbsp;मामले&nbsp;से&nbsp;जुड़े&nbsp;अहम&nbsp;सुराग&nbsp;लगे&nbsp;हैं।&nbsp;पुलिस&nbsp;ने&nbsp;घटना&nbsp;में&nbsp;शामिल&nbsp;दोनों&nbsp;संदिग्ध&nbsp;हमलावरों&nbsp;की&nbsp;पहली&nbsp;तस्वीर&nbsp;हासिल&nbsp;कर&nbsp;ली&nbsp;है,&nbsp;जिसके&nbsp;आधार&nbsp;पर&nbsp;उनकी&nbsp;तलाश&nbsp;में&nbsp;अलग-अलग&nbsp;ठिकानों&nbsp;पर&nbsp;दबिश&nbsp;दी&nbsp;जा&nbsp;रही&nbsp;है।</span></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">उपमुख्यमंत्री&nbsp;ने&nbsp;की&nbsp;मुलाकात</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">घटना&nbsp;की&nbsp;सूचना&nbsp;मिलते&nbsp;ही&nbsp;महाराष्ट्र&nbsp;के&nbsp;उपमुख्यमंत्री&nbsp;एकनाथ&nbsp;शिंदे&nbsp;अभिनेता&nbsp;के&nbsp;आवास&nbsp;पर&nbsp;पहुंचे।&nbsp;उन्होंने&nbsp;घायल&nbsp;टाइगर&nbsp;श्रॉफ&nbsp;से&nbsp;मुलाकात&nbsp;कर&nbsp;घटना&nbsp;की&nbsp;जानकारी&nbsp;ली&nbsp;और&nbsp;उनके&nbsp;स्वास्थ्य&nbsp;का&nbsp;हाल&nbsp;जाना।&nbsp;प्रशासन&nbsp;ने&nbsp;मामले&nbsp;में&nbsp;सख्त&nbsp;कार्रवाई&nbsp;और&nbsp;सुरक्षा&nbsp;का&nbsp;भरोसा&nbsp;दिया&nbsp;है।</span></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">FWICE&nbsp;ने&nbsp;जताई&nbsp;गहरी&nbsp;चिंता,&nbsp;सुरक्षा&nbsp;की&nbsp;उठाई&nbsp;मांग</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">फेडरेशन&nbsp;ऑफ&nbsp;वेस्टर्न&nbsp;इंडिया&nbsp;सिने&nbsp;एम्प्लॉइज&nbsp;(FWICE)&nbsp;ने&nbsp;इस&nbsp;हमले&nbsp;की&nbsp;कड़े&nbsp;शब्दों&nbsp;में&nbsp;निंदा&nbsp;की&nbsp;है।&nbsp;संगठन&nbsp;ने&nbsp;फिल्म&nbsp;निर्माता&nbsp;रोहित&nbsp;शेट्टी&nbsp;पर&nbsp;हुए&nbsp;पूर्व&nbsp;हमले&nbsp;का&nbsp;हवाला&nbsp;देते&nbsp;हुए&nbsp;फिल्म&nbsp;बिरादरी&nbsp;की&nbsp;सुरक्षा&nbsp;पर&nbsp;गंभीर&nbsp;सवाल&nbsp;खड़े&nbsp;किए&nbsp;हैं:</span></p><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">त्वरित&nbsp;और&nbsp;निष्पक्ष&nbsp;जांच:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;महाराष्ट्र&nbsp;सरकार&nbsp;और&nbsp;मुंबई&nbsp;पुलिस&nbsp;से&nbsp;मांग&nbsp;की&nbsp;गई&nbsp;है&nbsp;कि&nbsp;मामले&nbsp;की&nbsp;तेजी&nbsp;से&nbsp;जांच&nbsp;कर&nbsp;दोषियों&nbsp;को&nbsp;जल्द&nbsp;से&nbsp;जल्द&nbsp;कानून&nbsp;के&nbsp;कटघरे&nbsp;में&nbsp;लाया&nbsp;जाए।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">टाइगर&nbsp;और&nbsp;परिवार&nbsp;को&nbsp;सुरक्षा:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;अभिनेता&nbsp;और&nbsp;उनके&nbsp;परिजनों&nbsp;के&nbsp;लिए&nbsp;विशेष&nbsp;सुरक्षा&nbsp;घेरा&nbsp;मुहैया&nbsp;कराने&nbsp;की&nbsp;अपील&nbsp;की&nbsp;गई&nbsp;है।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">भयमुक्त&nbsp;माहौल&nbsp;की&nbsp;अपील:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;फिल्म&nbsp;उद्योग&nbsp;के&nbsp;आर्थिक&nbsp;और&nbsp;सांस्कृतिक&nbsp;महत्व&nbsp;को&nbsp;रेखांकित&nbsp;करते&nbsp;हुए&nbsp;संगठन&nbsp;ने&nbsp;कहा&nbsp;कि&nbsp;कलाकारों&nbsp;और&nbsp;तकनीशियनों&nbsp;के&nbsp;लिए&nbsp;सुरक्षित&nbsp;और&nbsp;भयमुक्त&nbsp;कामकाजी&nbsp;माहौल&nbsp;सुनिश्चित&nbsp;किया&nbsp;जाना&nbsp;जरूरी&nbsp;है।</span></li></ul><p></p>',
  'General',
  '["#TigerShroff","#TigerShroffFiring","#BollywoodNews","#JuhuFiring","#BreakingNews"]',
