) VALUES (
  'jGttpQ7J4vqdEdjMhQMS',
  '19-25-jMhQMS',
  'कोलकाता के चोरबागान दुर्गा पूजा पंडाल में भारी भगदड़: 19 श्रद्धालुओं की मौत, 25 घायल',
  'बारिश&nbsp;और&nbsp;संकरी&nbsp;गली&nbsp;में&nbsp;मची&nbsp;अफरा-तफरी&nbsp;के&nbsp;बाद&nbsp;12&nbsp;लोग&nbsp;हिरासत&nbsp;में&nbsp;|&nbsp;राज्य&nbsp;सरकार&nbsp;ने&nbsp;₹25&nbsp;लाख&nbsp;और&nbsp;नौकरी,&nbs...',
  '<p><strong style="font-size: 1rem; background-color: inherit; color: rgb(31, 31, 31);">बारिश&nbsp;और&nbsp;संकरी&nbsp;गली&nbsp;में&nbsp;मची&nbsp;अफरा-तफरी&nbsp;के&nbsp;बाद&nbsp;12&nbsp;लोग&nbsp;हिरासत&nbsp;में&nbsp;|&nbsp;राज्य&nbsp;सरकार&nbsp;ने&nbsp;₹25&nbsp;लाख&nbsp;और&nbsp;नौकरी,&nbsp;केंद्र&nbsp;ने&nbsp;₹2&nbsp;लाख&nbsp;मुआवजे&nbsp;की&nbsp;घोषणा&nbsp;की</strong></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">कोलकाता:</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">उत्तरी&nbsp;कोलकाता&nbsp;के&nbsp;प्रसिद्ध&nbsp;&#39;चोरबागान&nbsp;सार्वजनीन&nbsp;दुर्गोत्सव&nbsp;समिति&#39;&nbsp;पूजा&nbsp;पंडाल&nbsp;में&nbsp;शनिवार&nbsp;शाम&nbsp;सप्तमी&nbsp;के&nbsp;मौके&nbsp;पर&nbsp;मची&nbsp;भीषण&nbsp;भगदड़&nbsp;में&nbsp;कम&nbsp;से&nbsp;कम&nbsp;19&nbsp;श्रद्धालुओं&nbsp;की&nbsp;दर्दनाक&nbsp;मौत&nbsp;हो&nbsp;गई,&nbsp;जबकि&nbsp;25&nbsp;अन्य&nbsp;गंभीर&nbsp;रूप&nbsp;से&nbsp;घायल&nbsp;हो&nbsp;गए।&nbsp;हावड़ा&nbsp;ब्रिज&nbsp;से&nbsp;लगभग&nbsp;दो&nbsp;किलोमीटर&nbsp;दूर&nbsp;स्थित&nbsp;इस&nbsp;ऐतिहासिक&nbsp;पूजा&nbsp;स्थल&nbsp;पर&nbsp;यह&nbsp;हादसा&nbsp;शाम&nbsp;करीब&nbsp;7:30&nbsp;बजे&nbsp;हुआ।&nbsp;हादसे&nbsp;के&nbsp;बाद&nbsp;प्रशासन&nbsp;ने&nbsp;चोरबागान&nbsp;सहित&nbsp;चेतला&nbsp;अग्रणी&nbsp;और&nbsp;ताला&nbsp;प्रत्यय&nbsp;जैसे&nbsp;कई&nbsp;अन्य&nbsp;भीड़भाड़&nbsp;वाले&nbsp;पूजा&nbsp;पंडालों&nbsp;को&nbsp;भी&nbsp;एहतियातन&nbsp;बंद&nbsp;करा&nbsp;दिया&nbsp;है।</span></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">बारिश&nbsp;और&nbsp;संकरी&nbsp;गली&nbsp;बनी&nbsp;हादसे&nbsp;की&nbsp;वजह</span></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">प्रत्यक्षदर्शियों&nbsp;और&nbsp;शुरुआती&nbsp;रिपोर्टों&nbsp;के&nbsp;अनुसार,&nbsp;शनिवार&nbsp;शाम&nbsp;अचानक&nbsp;हुई&nbsp;तेज&nbsp;बारिश&nbsp;के&nbsp;कारण&nbsp;सड़कें&nbsp;फिसलन&nbsp;भरी&nbsp;हो&nbsp;गई&nbsp;थीं।&nbsp;बारिश&nbsp;से&nbsp;बचने&nbsp;के&nbsp;लिए&nbsp;बड़ी&nbsp;संख्या&nbsp;में&nbsp;श्रद्धालु&nbsp;संकरी&nbsp;गली&nbsp;से&nbsp;होते&nbsp;हुए&nbsp;पंडाल&nbsp;की&nbsp;ओर&nbsp;तेजी&nbsp;से&nbsp;बढ़े।&nbsp;इसी&nbsp;दौरान&nbsp;आयोजकों&nbsp;की&nbsp;ओर&nbsp;से&nbsp;की&nbsp;गई&nbsp;एक&nbsp;घोषणा&nbsp;के&nbsp;बाद&nbsp;अफरा-तफरी&nbsp;मच&nbsp;गई।&nbsp;फिसलन&nbsp;के&nbsp;कारण&nbsp;लोग&nbsp;एक-दूसरे&nbsp;के&nbsp;ऊपर&nbsp;गिरते&nbsp;चले&nbsp;गए,&nbsp;जिसने&nbsp;कुछ&nbsp;ही&nbsp;पलों&nbsp;में&nbsp;विकराल&nbsp;भगदड़&nbsp;का&nbsp;रूप&nbsp;ले&nbsp;लिया।</span><img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/jGttpQ7J4vqdEdjMhQMS-1.webp"></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">12&nbsp;लोग&nbsp;हिरासत&nbsp;में,&nbsp;जांच&nbsp;के&nbsp;लिए&nbsp;उच्च&nbsp;न्यायालय&nbsp;से&nbsp;कमेटी&nbsp;की&nbsp;मांग</span></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">घटना&nbsp;के&nbsp;तुरंत&nbsp;बाद&nbsp;पुलिस&nbsp;ने&nbsp;कार्रवाई&nbsp;करते&nbsp;हुए&nbsp;पूजा&nbsp;समिति&nbsp;के&nbsp;सदस्यों,&nbsp;निजी&nbsp;सुरक्षा&nbsp;एजेंसी&nbsp;के&nbsp;कर्मियों&nbsp;और&nbsp;भीड़&nbsp;प्रबंधन&nbsp;से&nbsp;जुड़े&nbsp;12&nbsp;लोगों&nbsp;को&nbsp;हिरासत&nbsp;में&nbsp;ले&nbsp;लिया&nbsp;है।&nbsp;मुख्यमंत्री&nbsp;शुभेंदु&nbsp;अधिकारी&nbsp;ने&nbsp;हादसे&nbsp;पर&nbsp;दुख&nbsp;जताते&nbsp;हुए&nbsp;कहा&nbsp;कि&nbsp;वह&nbsp;कलकत्ता&nbsp;उच्च&nbsp;न्यायालय&nbsp;के&nbsp;मुख्य&nbsp;न्यायाधीश&nbsp;को&nbsp;पत्र&nbsp;लिखकर&nbsp;एक&nbsp;स्वतंत्र&nbsp;&#39;फैक्ट-फाइंडिंग&nbsp;कमेटी&#39;&nbsp;गठित&nbsp;करने&nbsp;का&nbsp;अनुरोध&nbsp;करेंगे।&nbsp;इस&nbsp;जांच&nbsp;दल&nbsp;में&nbsp;स्पेशल&nbsp;टास्क&nbsp;फोर्स&nbsp;(STF)&nbsp;और&nbsp;फॉरेंसिक&nbsp;विशेषज्ञों&nbsp;को&nbsp;शामिल&nbsp;किया&nbsp;जाएगा।</span></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">मुआवजे&nbsp;और&nbsp;सहायता&nbsp;का&nbsp;ऐलान</span></h3><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">राज्य&nbsp;सरकार:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;मृतकों&nbsp;के&nbsp;परिजनों&nbsp;को&nbsp;₹25&nbsp;लाख&nbsp;की&nbsp;आर्थिक&nbsp;सहायता&nbsp;और&nbsp;परिवार&nbsp;के&nbsp;एक&nbsp;सदस्य&nbsp;को&nbsp;सरकारी&nbsp;नौकरी&nbsp;दी&nbsp;जाएगी।&nbsp;घायलों&nbsp;को&nbsp;₹5&nbsp;लाख&nbsp;दिए&nbsp;जाएंगे&nbsp;और&nbsp;उनके&nbsp;इलाज&nbsp;का&nbsp;पूरा&nbsp;खर्च&nbsp;राज्य&nbsp;सरकार&nbsp;उठाएगी।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">केंद्र&nbsp;सरकार:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;प्रधानमंत्री&nbsp;नरेंद्र&nbsp;मोदी&nbsp;ने&nbsp;प्रधानमंत्री&nbsp;राष्ट्रीय&nbsp;राहत&nbsp;कोष&nbsp;से&nbsp;मृतकों&nbsp;के&nbsp;परिजनों&nbsp;को&nbsp;₹2&nbsp;लाख&nbsp;और&nbsp;घायलों&nbsp;को&nbsp;₹50,000&nbsp;की&nbsp;सहायता&nbsp;राशि&nbsp;देने&nbsp;की&nbsp;घोषणा&nbsp;की।</span></li></ul><p><span style="background-color: inherit; color: rgb(31, 31, 31);">राष्ट्रपति&nbsp;द्रौपदी&nbsp;मुर्मू,&nbsp;प्रधानमंत्री&nbsp;नरेंद्र&nbsp;मोदी&nbsp;और&nbsp;पूर्व&nbsp;मुख्यमंत्री&nbsp;ममता&nbsp;बनर्जी&nbsp;ने&nbsp;हादसे&nbsp;पर&nbsp;गहरा&nbsp;शोक&nbsp;व्यक्त&nbsp;किया।&nbsp;राज्य&nbsp;के&nbsp;दो&nbsp;दिवसीय&nbsp;दौरे&nbsp;पर&nbsp;पहुंचे&nbsp;केंद्रीय&nbsp;गृह&nbsp;मंत्री&nbsp;अमित&nbsp;शाह&nbsp;ने&nbsp;रविवार&nbsp;के&nbsp;अपने&nbsp;सभी&nbsp;निर्धारित&nbsp;कार्यक्रम&nbsp;रद्द&nbsp;कर&nbsp;घायलों&nbsp;से&nbsp;अस्पताल&nbsp;में&nbsp;मिलने&nbsp;का&nbsp;फैसला&nbsp;किया&nbsp;है।</span></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">राजनीतिक&nbsp;खींचतान&nbsp;तेज</span></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">हादसे&nbsp;के&nbsp;तुरंत&nbsp;बाद&nbsp;राज्य&nbsp;में&nbsp;राजनीतिक&nbsp;आरोप-प्रत्यारोप&nbsp;शुरू&nbsp;हो&nbsp;गए&nbsp;हैं:</span></p><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">तृणमूल&nbsp;कांग्रेस&nbsp;(TMC):</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;पार्टी&nbsp;ने&nbsp;लचर&nbsp;भीड़&nbsp;प्रबंधन&nbsp;और&nbsp;पुलिस&nbsp;की&nbsp;अपर्याप्त&nbsp;तैनाती&nbsp;को&nbsp;हादसे&nbsp;का&nbsp;जिम्मेदार&nbsp;ठहराया।&nbsp;टीएमसी&nbsp;ने&nbsp;आरोप&nbsp;लगाया&nbsp;कि&nbsp;पूजा&nbsp;समिति&nbsp;के&nbsp;कर्ताधर्ताओं&nbsp;में&nbsp;मुख्यमंत्री&nbsp;के&nbsp;करीबी&nbsp;रिश्तेदार&nbsp;शामिल&nbsp;हैं&nbsp;और&nbsp;स्थानीय&nbsp;भाजपा&nbsp;विधायक&nbsp;इस&nbsp;समिति&nbsp;के&nbsp;अध्यक्ष&nbsp;हैं।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">प्रशासन&nbsp;का&nbsp;रुख:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;मुख्यमंत्री&nbsp;ने&nbsp;आरोपों&nbsp;के&nbsp;बीच&nbsp;निष्पक्ष&nbsp;जांच&nbsp;का&nbsp;भरोसा&nbsp;दिलाते&nbsp;हुए&nbsp;शहर&nbsp;के&nbsp;सभी&nbsp;अन्य&nbsp;पूजा&nbsp;आयोजकों&nbsp;को&nbsp;सुरक्षा&nbsp;और&nbsp;भीड़&nbsp;नियंत्रण&nbsp;के&nbsp;कड़े&nbsp;इंतजाम&nbsp;सुनिश्चित&nbsp;करने&nbsp;के&nbsp;निर्देश&nbsp;दिए&nbsp;हैं।</span></li></ul><p></p>',
