) VALUES (
  'fhH2nbXDGvahWS9yz7Bn',
  'fhH2nbXDGvahWS9yz7Bn-9yz7Bn',
  'गोड्डा: बसंतराय के गोपीचक में भीषण अगलगी, चार दुकानें जलकर राख',
  'मुख्य&nbsp;सड़क&nbsp;पर&nbsp;भड़की&nbsp;आग&nbsp;से&nbsp;मची&nbsp;अफरा-तफरी;&nbsp;ग्रामीणों&nbsp;की&nbsp;मशक्कत&nbsp;से&nbsp;बुझी&nbsp;आग,&nbsp;लाखों&nbsp;के&nbsp;नुकसान&nbsp;की&nbsp;आशंका बसंतराय&nbsp...',
  '<h1><em style="font-size: 1rem; background-color: inherit; color: rgb(31, 31, 31);">मुख्य&nbsp;सड़क&nbsp;पर&nbsp;भड़की&nbsp;आग&nbsp;से&nbsp;मची&nbsp;अफरा-तफरी;&nbsp;ग्रामीणों&nbsp;की&nbsp;मशक्कत&nbsp;से&nbsp;बुझी&nbsp;आग,&nbsp;लाखों&nbsp;के&nbsp;नुकसान&nbsp;की&nbsp;आशंका</em></h1><p><strong style="font-size: 1rem; background-color: inherit; color: rgb(31, 31, 31);">बसंतराय&nbsp;(गोड्डा):</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">प्रखंड&nbsp;क्षेत्र&nbsp;की&nbsp;कैथिया&nbsp;पंचायत&nbsp;अंतर्गत&nbsp;गोपीचक&nbsp;गांव&nbsp;में&nbsp;मुख्य&nbsp;सड़क&nbsp;किनारे&nbsp;स्थित&nbsp;दुकानों&nbsp;में&nbsp;भीषण&nbsp;आग&nbsp;लग&nbsp;गई।&nbsp;इस&nbsp;अगलगी&nbsp;की&nbsp;घटना&nbsp;में&nbsp;चार&nbsp;दुकानें&nbsp;पूरी&nbsp;तरह&nbsp;जलकर&nbsp;राख&nbsp;हो&nbsp;गईं।&nbsp;आग&nbsp;की&nbsp;लपटें&nbsp;इतनी&nbsp;विकराल&nbsp;थीं&nbsp;कि&nbsp;जब&nbsp;तक&nbsp;लोग&nbsp;कुछ&nbsp;समझ&nbsp;पाते,&nbsp;दुकानों&nbsp;में&nbsp;रखा&nbsp;सारा&nbsp;सामान&nbsp;जलकर&nbsp;खाक&nbsp;हो&nbsp;गया।</span></p><h3><strong style="background-color: inherit; color: rgb(31, 31, 31);">गांव&nbsp;में&nbsp;अफरा-तफरी,&nbsp;ग्रामीणों&nbsp;ने&nbsp;पाया&nbsp;काबू</strong></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">घटना&nbsp;के&nbsp;बाद&nbsp;आसपास&nbsp;के&nbsp;इलाके&nbsp;में&nbsp;हड़कंप&nbsp;मच&nbsp;गया&nbsp;और&nbsp;घटनास्थल&nbsp;पर&nbsp;लोगों&nbsp;की&nbsp;भारी&nbsp;भीड़&nbsp;जुट&nbsp;गई।&nbsp;ग्रामीणों&nbsp;ने&nbsp;साहस&nbsp;दिखाते&nbsp;हुए&nbsp;तुरंत&nbsp;राहत&nbsp;कार्य&nbsp;शुरू&nbsp;किया।&nbsp;काफी&nbsp;मशक्कत&nbsp;और&nbsp;कड़ी&nbsp;मेहनत&nbsp;के&nbsp;बाद&nbsp;आग&nbsp;पर&nbsp;काबू&nbsp;पाया&nbsp;गया,&nbsp;लेकिन&nbsp;तब&nbsp;तक&nbsp;दुकानों&nbsp;में&nbsp;मौजूद&nbsp;संपत्ति&nbsp;जल&nbsp;चुकी&nbsp;थी।</span></p><h3><strong style="background-color: inherit; color: rgb(31, 31, 31);">नुकसान&nbsp;का&nbsp;आकलन&nbsp;बाकी,&nbsp;कारण&nbsp;अज्ञात</strong></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">इस&nbsp;अगलगी&nbsp;से&nbsp;पीड़ित&nbsp;व्यवसायियों&nbsp;को&nbsp;भारी&nbsp;आर्थिक&nbsp;नुकसान&nbsp;का&nbsp;अनुमान&nbsp;है।&nbsp;आग&nbsp;किस&nbsp;वजह&nbsp;से&nbsp;लगी&nbsp;और&nbsp;कुल&nbsp;कितने&nbsp;मूल्य&nbsp;की&nbsp;संपत्ति&nbsp;का&nbsp;नुकसान&nbsp;हुआ&nbsp;है,&nbsp;इसका&nbsp;सटीक&nbsp;ब्योरा&nbsp;फिलहाल&nbsp;स्पष्ट&nbsp;नहीं&nbsp;हो&nbsp;सका&nbsp;है।</span></p><h3><strong style="background-color: inherit; color: rgb(31, 31, 31);">मुआवजे&nbsp;और&nbsp;जांच&nbsp;की&nbsp;दरकार</strong><img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/fhH2nbXDGvahWS9yz7Bn-1.webp"></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">हादसे&nbsp;के&nbsp;बाद&nbsp;इलाके&nbsp;में&nbsp;चिंता&nbsp;का&nbsp;माहौल&nbsp;है।&nbsp;ग्रामीणों&nbsp;और&nbsp;पीड़ित&nbsp;परिवारों&nbsp;के&nbsp;सामने&nbsp;अब&nbsp;दो&nbsp;मुख्य&nbsp;सवाल&nbsp;हैं—आग&nbsp;लगने&nbsp;की&nbsp;वास्तविक&nbsp;वजह&nbsp;क्या&nbsp;थी&nbsp;और&nbsp;प्रभावित&nbsp;दुकानदारों&nbsp;को&nbsp;हुए&nbsp;इस&nbsp;भारी&nbsp;नुकसान&nbsp;की&nbsp;भरपाई&nbsp;प्रशासन&nbsp;किस&nbsp;तरह&nbsp;सुनिश्चित&nbsp;करेगा।&nbsp;पीड़ित&nbsp;दुकानदार&nbsp;अब&nbsp;सरकारी&nbsp;स्तर&nbsp;पर&nbsp;सहायता&nbsp;और&nbsp;मुआवजे&nbsp;की&nbsp;उम्मीद&nbsp;लगाए&nbsp;बैठे&nbsp;हैं।</span></p><p></p>',
