) VALUES (
  'cgLfTKuciQA7c2OtukCM',
  'cgLfTKuciQA7c2OtukCM-OtukCM',
  'बेलडीहा के फूलवड़िया में मुख्य सड़क बदहाल, गड्ढों में तब्दील हुआ मार्ग; हर पल बड़े हादसे की आशंका',
  'बसंतराय&nbsp;और&nbsp;हनवारा&nbsp;को&nbsp;जोड़ने&nbsp;वाली&nbsp;प्रमुख&nbsp;सड़क&nbsp;की&nbsp;स्थिति&nbsp;दयनीय,&nbsp;राहगीरों&nbsp;व&nbsp;ग्रामीणों&nbsp;का&nbsp;आवागमन&nbsp;दूभर बसंतराय&nbsp;(गोड्डा):...',
  '<p class="ql-align-center"></p><p><em style="background-color: inherit; color: rgb(31, 31, 31);">बसंतराय&nbsp;और&nbsp;हनवारा&nbsp;को&nbsp;जोड़ने&nbsp;वाली&nbsp;प्रमुख&nbsp;सड़क&nbsp;की&nbsp;स्थिति&nbsp;दयनीय,&nbsp;राहगीरों&nbsp;व&nbsp;ग्रामीणों&nbsp;का&nbsp;आवागमन&nbsp;दूभर</em></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">बसंतराय&nbsp;(गोड्डा):</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">गोड्डा&nbsp;जिले&nbsp;के&nbsp;बसंतराय&nbsp;प्रखंड&nbsp;अंतर्गत&nbsp;बेलडीहा&nbsp;पंचायत&nbsp;के&nbsp;फूलवड़िया&nbsp;गांव&nbsp;में&nbsp;मुख्य&nbsp;सड़क&nbsp;की&nbsp;बदहाली&nbsp;से&nbsp;आम&nbsp;जनजीवन&nbsp;बुरी&nbsp;तरह&nbsp;प्रभावित&nbsp;हो&nbsp;रहा&nbsp;है।&nbsp;सड़क&nbsp;पर&nbsp;जगह-जगह&nbsp;बने&nbsp;गड्ढों&nbsp;और&nbsp;उखड़ी&nbsp;गिट्टियों&nbsp;के&nbsp;कारण&nbsp;यह&nbsp;मार्ग&nbsp;पूरी&nbsp;तरह&nbsp;जर्जर&nbsp;हो&nbsp;चुका&nbsp;है,&nbsp;जिससे&nbsp;राहगीरों&nbsp;और&nbsp;वाहन&nbsp;चालकों&nbsp;को&nbsp;रोज&nbsp;भारी&nbsp;परेशानियों&nbsp;का&nbsp;सामना&nbsp;करना&nbsp;पड़&nbsp;रहा&nbsp;है।</span></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">बसंतराय-हनवारा&nbsp;का&nbsp;प्रमुख&nbsp;संपर्क&nbsp;मार्ग:</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">स्थानीय&nbsp;ग्रामीणों&nbsp;के&nbsp;अनुसार,&nbsp;यह&nbsp;सड़क&nbsp;क्षेत्र&nbsp;के&nbsp;लिए&nbsp;बेहद&nbsp;महत्वपूर्ण&nbsp;है,&nbsp;क्योंकि&nbsp;यह&nbsp;बसंतराय&nbsp;और&nbsp;हनवारा&nbsp;को&nbsp;सीधे&nbsp;जोड़ने&nbsp;का&nbsp;मुख्य&nbsp;जरिया&nbsp;है।&nbsp;व्यापारिक&nbsp;और&nbsp;निजी&nbsp;कार्यों&nbsp;के&nbsp;लिए&nbsp;रोजाना&nbsp;सैकड़ों&nbsp;लोग&nbsp;इस&nbsp;रास्ते&nbsp;से&nbsp;आवागमन&nbsp;करते&nbsp;हैं।&nbsp;सड़क&nbsp;की&nbsp;खस्ताहाली&nbsp;के&nbsp;कारण&nbsp;यहां&nbsp;हर&nbsp;समय&nbsp;किसी&nbsp;बड़ी&nbsp;दुर्घटना&nbsp;की&nbsp;आशंका&nbsp;बनी&nbsp;रहती&nbsp;है,&nbsp;विशेषकर&nbsp;रात&nbsp;के&nbsp;समय&nbsp;गड्ढों&nbsp;का&nbsp;अंदाजा&nbsp;न&nbsp;मिलने&nbsp;से&nbsp;स्थिति&nbsp;और&nbsp;भी&nbsp;जोखिम&nbsp;भरी&nbsp;हो&nbsp;जाती&nbsp;है।</span></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">प्रशासनिक&nbsp;उदासीनता&nbsp;पर&nbsp;उठे&nbsp;सवाल:</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">लंबे&nbsp;समय&nbsp;से&nbsp;जर्जर&nbsp;पड़ी&nbsp;इस&nbsp;सड़क&nbsp;की&nbsp;सुध&nbsp;न&nbsp;लिए&nbsp;जाने&nbsp;से&nbsp;स्थानीय&nbsp;लोगों&nbsp;में&nbsp;नाराजगी&nbsp;है।&nbsp;राहगीरों&nbsp;का&nbsp;कहना&nbsp;है&nbsp;कि&nbsp;रोजाना&nbsp;इस&nbsp;संकट&nbsp;से&nbsp;जूझने&nbsp;के&nbsp;बावजूद&nbsp;जिम्मेदार&nbsp;विभाग&nbsp;और&nbsp;अधिकारियों&nbsp;की&nbsp;नजर&nbsp;इस&nbsp;बदहाल&nbsp;सड़क&nbsp;पर&nbsp;नहीं&nbsp;पड़&nbsp;रही&nbsp;है।</span></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">शीघ्र&nbsp;मरम्मत&nbsp;की&nbsp;मांग:</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">ग्रामीणों&nbsp;एवं&nbsp;राहगीरों&nbsp;ने&nbsp;जिला&nbsp;प्रशासन&nbsp;और&nbsp;संबंधित&nbsp;विभाग&nbsp;से&nbsp;मांग&nbsp;की&nbsp;है&nbsp;कि&nbsp;मामले&nbsp;को&nbsp;गंभीरता&nbsp;से&nbsp;लेते&nbsp;हुए&nbsp;सड़क&nbsp;की&nbsp;शीघ्र&nbsp;मरम्मत&nbsp;कराई&nbsp;जाए,&nbsp;ताकि&nbsp;क्षेत्रवासियों&nbsp;को&nbsp;आवागमन&nbsp;में&nbsp;राहत&nbsp;मिल&nbsp;सके&nbsp;और&nbsp;संभावित&nbsp;हादसों&nbsp;को&nbsp;टाला&nbsp;जा&nbsp;सके।</span></p><p></p>',
  'General',
  '["#GroundLevelReporting","#viralkhabar","#Dimageroad","#localnews","#exclusive"]',
  'https://youtube.com/shorts/mvQMbPBZrk4?si=WTnvX9Mkbxw3MYen',
