  published_at, updated_at, version
) VALUES (
  '55W3HLJtA76DBz0xJWqx',
  '12-300-0xJWqx',
  'रियाद एयरपोर्ट पर हूती विद्रोहियों का घातक हमला: 12 की मौत, 300 से अधिक घायल; वैश्विक स्तर पर तीखी निंदा',
  'अमेरिकी&nbsp;राष्ट्रपति&nbsp;ट्रंप&nbsp;ने&nbsp;हमले&nbsp;को&nbsp;बताया&nbsp;‘भयावह’,&nbsp;सऊदी&nbsp;गठबंधन&nbsp;के&nbsp;साथ&nbsp;सैन्य&nbsp;कार्रवाई&nbsp;में&nbsp;शामिल&nbsp;होने&nbsp;पर&nbsp;विचार&n...',
  '<h1><em style="font-weight: inherit; background-color: inherit; font-size: 1rem; color: rgb(31, 31, 31);">अमेरिकी&nbsp;राष्ट्रपति&nbsp;ट्रंप&nbsp;ने&nbsp;हमले&nbsp;को&nbsp;बताया&nbsp;‘भयावह’,&nbsp;सऊदी&nbsp;गठबंधन&nbsp;के&nbsp;साथ&nbsp;सैन्य&nbsp;कार्रवाई&nbsp;में&nbsp;शामिल&nbsp;होने&nbsp;पर&nbsp;विचार&nbsp;तेज</em></h1><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">विशेष&nbsp;संवाददाता&nbsp;/&nbsp;एजेंसियां</strong></p><p><strong style="background-color: inherit; color: rgb(31, 31, 31);">रियाद,&nbsp;11&nbsp;अक्टूबर&nbsp;2026</strong></p><p><span style="background-color: inherit; color: rgb(31, 31, 31);">यमन&nbsp;के&nbsp;हूती&nbsp;विद्रोहियों&nbsp;द्वारा&nbsp;सऊदी&nbsp;अरब&nbsp;की&nbsp;राजधानी&nbsp;स्थित&nbsp;किंग&nbsp;खालिद&nbsp;अंतरराष्ट्रीय&nbsp;हवाई&nbsp;अड्डे&nbsp;पर&nbsp;किए&nbsp;गए&nbsp;भीषण&nbsp;हमले&nbsp;में&nbsp;कम&nbsp;से&nbsp;कम&nbsp;12&nbsp;लोगों&nbsp;की&nbsp;मौत&nbsp;हो&nbsp;गई,&nbsp;जबकि&nbsp;300&nbsp;से&nbsp;अधिक&nbsp;लोग&nbsp;घायल&nbsp;हो&nbsp;गए&nbsp;हैं।&nbsp;सऊदी&nbsp;अधिकारियों&nbsp;के&nbsp;अनुसार,&nbsp;इस&nbsp;सप्ताह&nbsp;रियाद&nbsp;हवाई&nbsp;अड्डे&nbsp;को&nbsp;निशाना&nbsp;बनाकर&nbsp;किया&nbsp;गया&nbsp;यह&nbsp;तीसरा&nbsp;हमला&nbsp;था&nbsp;और&nbsp;पिछले&nbsp;एक&nbsp;दशक&nbsp;से&nbsp;अधिक&nbsp;समय&nbsp;में&nbsp;देश&nbsp;के&nbsp;भीतर&nbsp;हुआ&nbsp;सबसे&nbsp;घातक&nbsp;हमला&nbsp;माना&nbsp;जा&nbsp;रहा&nbsp;है।</span></p><h3><strong style="background-color: inherit; color: rgb(31, 31, 31);">मृतकों&nbsp;में&nbsp;कई&nbsp;देशों&nbsp;के&nbsp;नागरिक&nbsp;शामिल</strong></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">सऊदी&nbsp;नागरिक&nbsp;उड्डयन&nbsp;प्राधिकरण&nbsp;की&nbsp;ओर&nbsp;से&nbsp;जारी&nbsp;जानकारी&nbsp;के&nbsp;अनुसार,&nbsp;शनिवार&nbsp;को&nbsp;हुए&nbsp;इस&nbsp;हमले&nbsp;में&nbsp;मारे&nbsp;गए&nbsp;लोगों&nbsp;में&nbsp;विभिन्न&nbsp;देशों&nbsp;के&nbsp;नागरिक&nbsp;शामिल&nbsp;हैं:</span></p><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">सऊदी&nbsp;अरब:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;4&nbsp;नागरिक</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">बांग्लादेश:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;2&nbsp;नागरिक</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">अमेरिका,&nbsp;जॉर्डन,&nbsp;फिलिस्तीन,&nbsp;सीरिया,&nbsp;सूडान&nbsp;एवं&nbsp;मिस्र:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;प्रत्येक&nbsp;देश&nbsp;से&nbsp;1-1&nbsp;नागरिक</span></li></ul><h3><strong style="background-color: inherit; color: rgb(31, 31, 31);">प्रमुख&nbsp;वैश्विक&nbsp;प्रतिक्रियाएं</strong></h3><h4><strong style="background-color: inherit; color: rgb(31, 31, 31);">अमेरिका:&nbsp;सैन्य&nbsp;हस्तक्षेप&nbsp;पर&nbsp;विचार</strong></h4><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">राष्ट्रपति&nbsp;डोनाल्ड&nbsp;ट्रंप</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;ने&nbsp;इस&nbsp;हमले&nbsp;की&nbsp;निंदा&nbsp;करते&nbsp;हुए&nbsp;इसे&nbsp;&quot;भयावह&quot;&nbsp;बताया।&nbsp;उन्होंने&nbsp;कहा&nbsp;कि&nbsp;वह&nbsp;जल्द&nbsp;ही&nbsp;सऊदी&nbsp;अरब&nbsp;के&nbsp;क्राउन&nbsp;प्रिंस&nbsp;मोहम्मद&nbsp;बिन&nbsp;सलमान&nbsp;से&nbsp;बातचीत&nbsp;करेंगे।&nbsp;ट्रंप&nbsp;ने&nbsp;संकेत&nbsp;दिया&nbsp;कि&nbsp;अमेरिका&nbsp;हूतियों&nbsp;के&nbsp;खिलाफ&nbsp;सऊदी&nbsp;अरब&nbsp;के&nbsp;अभियानों&nbsp;में&nbsp;सीधे&nbsp;तौर&nbsp;पर&nbsp;शामिल&nbsp;होने&nbsp;पर&nbsp;विचार&nbsp;कर&nbsp;रहा&nbsp;है:</span></li></ul><blockquote><em style="background-color: inherit; color: rgb(31, 31, 31);">&quot;हम&nbsp;इस&nbsp;पर&nbsp;गौर&nbsp;कर&nbsp;रहे&nbsp;हैं।&nbsp;हमें&nbsp;अभी&nbsp;हाल&nbsp;ही&nbsp;में&nbsp;इस&nbsp;हमले&nbsp;की&nbsp;जानकारी&nbsp;मिली&nbsp;है,&nbsp;इसलिए&nbsp;हम&nbsp;जल्द&nbsp;ही&nbsp;इस&nbsp;पर&nbsp;निर्णय&nbsp;लेंगे&nbsp;और&nbsp;तेजी&nbsp;से&nbsp;कदम&nbsp;उठाएंगे।&quot;</em></blockquote><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">अमेरिकी&nbsp;विदेश&nbsp;मंत्री&nbsp;मार्को&nbsp;रुबियो</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;ने&nbsp;हमले&nbsp;में&nbsp;एक&nbsp;अमेरिकी&nbsp;नागरिक&nbsp;के&nbsp;मारे&nbsp;जाने&nbsp;पर&nbsp;शोक&nbsp;व्यक्त&nbsp;किया&nbsp;और&nbsp;कहा&nbsp;कि&nbsp;अमेरिका&nbsp;सऊदी&nbsp;अरब&nbsp;और&nbsp;वहां&nbsp;के&nbsp;लोगों&nbsp;के&nbsp;साथ&nbsp;मजबूती&nbsp;से&nbsp;खड़ा&nbsp;है।</span></li></ul><h4><strong style="background-color: inherit; color: rgb(31, 31, 31);">संयुक्त&nbsp;राष्ट्र&nbsp;(UN):&nbsp;अंतरराष्ट्रीय&nbsp;कानून&nbsp;का&nbsp;उल्लंघन</strong></h4><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">महासचिव&nbsp;एंटोनियो&nbsp;गुटेरेस</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;ने&nbsp;गहरा&nbsp;दुख&nbsp;व्यक्त&nbsp;करते&nbsp;हुए&nbsp;कहा&nbsp;कि&nbsp;नागरिकों&nbsp;और&nbsp;नागरिक&nbsp;बुनियादी&nbsp;ढांचों&nbsp;(सिविलियन&nbsp;इंफ्रास्ट्रक्चर)&nbsp;को&nbsp;निशाना&nbsp;बनाना&nbsp;अंतरराष्ट्रीय&nbsp;कानून&nbsp;का&nbsp;उल्लंघन&nbsp;है&nbsp;और&nbsp;ऐसे&nbsp;हमलों&nbsp;को&nbsp;तुरंत&nbsp;रोका&nbsp;जाना&nbsp;चाहिए।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">यमन&nbsp;के&nbsp;लिए&nbsp;संयुक्त&nbsp;राष्ट्र&nbsp;के&nbsp;विशेष&nbsp;दूत&nbsp;हैंस&nbsp;ग्रंडबर्ग</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;ने&nbsp;इस&nbsp;घटना&nbsp;को&nbsp;एक&nbsp;&quot;गंभीर&nbsp;तनाव&nbsp;वृद्धि&quot;&nbsp;करार&nbsp;दिया।&nbsp;उन्होंने&nbsp;कहा&nbsp;कि&nbsp;इस&nbsp;तरह&nbsp;की&nbsp;कार्रवाइयां&nbsp;क्षेत्रीय&nbsp;सुरक्षा&nbsp;के&nbsp;लिए&nbsp;बड़ा&nbsp;खतरा&nbsp;हैं&nbsp;और&nbsp;शांति&nbsp;प्रयासों&nbsp;को&nbsp;जटिल&nbsp;बनाती&nbsp;हैं।</span></li></ul><h4><strong style="background-color: inherit; color: rgb(31, 31, 31);">मिस्र:&nbsp;संप्रभुता&nbsp;और&nbsp;सुरक्षा&nbsp;की&nbsp;अनदेखी</strong></h4><ul><li><span style="background-color: inherit; color: rgb(31, 31, 31);">मिस्र&nbsp;के&nbsp;विदेश&nbsp;मंत्रालय&nbsp;ने&nbsp;हमले&nbsp;की&nbsp;कड़ी&nbsp;निंदा&nbsp;करते&nbsp;हुए&nbsp;इसे&nbsp;अंतरराष्ट्रीय&nbsp;नियमों&nbsp;का&nbsp;खुला&nbsp;उल्लंघन&nbsp;तथा&nbsp;आम&nbsp;नागरिकों&nbsp;की&nbsp;सुरक्षा&nbsp;की&nbsp;अनदेखी&nbsp;बताया।</span></li></ul><h3><strong style="background-color: inherit; color: rgb(31, 31, 31);">पृष्ठभूमि</strong></h3><p><span style="color: rgb(31, 31, 31); background-color: inherit;">यह&nbsp;हमला&nbsp;ऐसे&nbsp;समय&nbsp;में&nbsp;हुआ&nbsp;है&nbsp;जब&nbsp;यमन&nbsp;में&nbsp;युद्ध&nbsp;की&nbsp;स्थिति&nbsp;और&nbsp;अधिक&nbsp;गंभीर&nbsp;हो&nbsp;गई&nbsp;है।&nbsp;ईरान&nbsp;समर्थित&nbsp;हूती&nbsp;विद्रोही&nbsp;अंतरराष्ट्रीय&nbsp;स्तर&nbsp;पर&nbsp;मान्यता&nbsp;प्राप्त&nbsp;यमन&nbsp;सरकार&nbsp;के&nbsp;नियंत्रण&nbsp;वाले&nbsp;क्षेत्रों&nbsp;पर&nbsp;दबाव&nbsp;बना&nbsp;रहे&nbsp;हैं,&nbsp;जबकि&nbsp;सऊदी&nbsp;अरब&nbsp;यमन&nbsp;सरकार&nbsp;के&nbsp;समर्थन&nbsp;में&nbsp;हूतियों&nbsp;के&nbsp;ठिकानों&nbsp;पर&nbsp;हवाई&nbsp;अभियान&nbsp;चला&nbsp;रहा&nbsp;है।&nbsp;विश्लेषकों&nbsp;के&nbsp;अनुसार,&nbsp;हवाई&nbsp;अड्डे&nbsp;पर&nbsp;हुआ&nbsp;यह&nbsp;हमला&nbsp;हूतियों&nbsp;की&nbsp;ओर&nbsp;से&nbsp;जवाबी&nbsp;कार्रवाई&nbsp;के&nbsp;रूप&nbsp;में&nbsp;देखा&nbsp;जा&nbsp;रहा&nbsp;था।</span></p><p></p><p></p>',
