) VALUES (
  'D0rzuZgQLpRC4J9EST0e',
  'D0rzuZgQLpRC4J9EST0e-9EST0e',
  'सर्दियों में नवजात की हिफाजत: गिरते पारे के बीच शिशुओं की विशेष देखभाल के लिए विशेषज्ञों की अहम सलाह',
  'विशेष&nbsp;संवाददाता&nbsp;|&nbsp;नई&nbsp;दिल्ली सर्दियों&nbsp;के&nbsp;मौसम&nbsp;में&nbsp;तापमान&nbsp;में&nbsp;गिरावट&nbsp;आते&nbsp;ही&nbsp;नवजात&nbsp;शिशुओं&nbsp;(Newborns)&nbsp;के&nbsp;स्वास्थ्य&nbsp...',
  '<p><img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/D0rzuZgQLpRC4J9EST0e-3.webp" alt="Article Photo"></p><p><img src="https://https://media.currentnews.blog/uploads/photo.jpg/img/D0rzuZgQLpRC4J9EST0e-3.webp" alt="Article Photo"></p><h1><strong style="font-size: 1rem; background-color: inherit; color: rgb(31, 31, 31);">विशेष&nbsp;संवाददाता&nbsp;|&nbsp;नई&nbsp;दिल्ली</strong></h1><p><span style="background-color: inherit; color: rgb(31, 31, 31);">सर्दियों&nbsp;के&nbsp;मौसम&nbsp;में&nbsp;तापमान&nbsp;में&nbsp;गिरावट&nbsp;आते&nbsp;ही&nbsp;नवजात&nbsp;शिशुओं&nbsp;(Newborns)&nbsp;के&nbsp;स्वास्थ्य&nbsp;को&nbsp;लेकर&nbsp;सतर्कता&nbsp;बरतना&nbsp;आवश्यक&nbsp;हो&nbsp;जाता&nbsp;है।&nbsp;बाल&nbsp;रोग&nbsp;विशेषज्ञों&nbsp;के&nbsp;अनुसार,&nbsp;शुरुआती&nbsp;महीनों&nbsp;में&nbsp;शिशुओं&nbsp;की&nbsp;रोग&nbsp;प्रतिरोधक&nbsp;क्षमता&nbsp;(इम्यूनिटी)&nbsp;वयस्कों&nbsp;की&nbsp;तुलना&nbsp;में&nbsp;काफी&nbsp;संवेदनशील&nbsp;होती&nbsp;है।&nbsp;ऐसे&nbsp;में&nbsp;थोड़ी&nbsp;सी&nbsp;भी&nbsp;लापरवाही&nbsp;सर्दी,&nbsp;जुकाम&nbsp;और&nbsp;मौसमी&nbsp;फ्लू&nbsp;का&nbsp;कारण&nbsp;बन&nbsp;सकती&nbsp;है।&nbsp;स्वास्थ्य&nbsp;विशेषज्ञों&nbsp;ने&nbsp;सर्दियों&nbsp;के&nbsp;दौरान&nbsp;नवजात&nbsp;शिशुओं&nbsp;को&nbsp;सुरक्षित&nbsp;और&nbsp;स्वस्थ&nbsp;रखने&nbsp;के&nbsp;लिए&nbsp;निम्नलिखित&nbsp;दिशा-निर्देश&nbsp;जारी&nbsp;किए&nbsp;हैं:</span></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">1.&nbsp;कपड़ों&nbsp;का&nbsp;&#39;प्लस&nbsp;वन&#39;&nbsp;नियम&nbsp;अपनाएं&nbsp;(Layering&nbsp;Rule)</span></h3><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">एक&nbsp;परत&nbsp;अतिरिक्त&nbsp;कपड़ा:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;शिशु&nbsp;को&nbsp;वयस्कों&nbsp;की&nbsp;तुलना&nbsp;में&nbsp;हमेशा&nbsp;कपड़ों&nbsp;की&nbsp;एक&nbsp;परत&nbsp;(Layer)&nbsp;अधिक&nbsp;पहनानी&nbsp;चाहिए।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">त्वचा&nbsp;के&nbsp;संपर्क&nbsp;में&nbsp;सिर्फ&nbsp;सूती:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;ऊनी&nbsp;(Woolen)&nbsp;कपड़े&nbsp;सीधे&nbsp;त्वचा&nbsp;पर&nbsp;पहनाने&nbsp;से&nbsp;रैशेज&nbsp;और&nbsp;एलर्जी&nbsp;का&nbsp;जोखिम&nbsp;रहता&nbsp;है।&nbsp;इसलिए&nbsp;सबसे&nbsp;पहले&nbsp;मुलायम&nbsp;सूती&nbsp;(Cotton)&nbsp;इनर&nbsp;पहनाएं,&nbsp;उसके&nbsp;ऊपर&nbsp;थर्मल&nbsp;या&nbsp;गर्म&nbsp;कपड़े&nbsp;डालें।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">सिर,&nbsp;कान&nbsp;और&nbsp;हाथ-पैर&nbsp;ढकें:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;शिशुओं&nbsp;के&nbsp;शरीर&nbsp;की&nbsp;गर्मी&nbsp;सिर&nbsp;और&nbsp;तलवों&nbsp;के&nbsp;जरिए&nbsp;तेजी&nbsp;से&nbsp;बाहर&nbsp;निकलती&nbsp;है।&nbsp;बाहर&nbsp;निकलते&nbsp;समय&nbsp;या&nbsp;सोते&nbsp;वक्त&nbsp;टोपी,&nbsp;मोजे&nbsp;और&nbsp;दस्ताने&nbsp;(Mittens)&nbsp;अवश्य&nbsp;पहनाएं।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">ओवरड्रेसिंग&nbsp;से&nbsp;बचें:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;बहुत&nbsp;अधिक&nbsp;भारी&nbsp;कपड़े&nbsp;लादने&nbsp;से&nbsp;पसीना&nbsp;आ&nbsp;सकता&nbsp;है,&nbsp;जिससे&nbsp;ओवरहीटिंग&nbsp;और&nbsp;घमौरियों&nbsp;जैसी&nbsp;समस्याएं&nbsp;हो&nbsp;सकती&nbsp;हैं।</span></li></ul><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">2.&nbsp;नियमित&nbsp;नहलाना&nbsp;जरूरी&nbsp;नहीं,&nbsp;गुनगुने&nbsp;तेल&nbsp;की&nbsp;मालिश&nbsp;असरदार</span></h3><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">हफ्ते&nbsp;में&nbsp;2–3&nbsp;बार&nbsp;स्नान&nbsp;पर्याप्त:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;ठंड&nbsp;के&nbsp;दिनों&nbsp;में&nbsp;रोजाना&nbsp;नहलाने&nbsp;के&nbsp;बजाय&nbsp;हफ्ते&nbsp;में&nbsp;2&nbsp;से&nbsp;3&nbsp;बार&nbsp;गुनगुने&nbsp;पानी&nbsp;से&nbsp;नहलाना&nbsp;पर्याप्त&nbsp;है।&nbsp;बाकी&nbsp;दिन&nbsp;गुनगुने&nbsp;पानी&nbsp;में&nbsp;सूती&nbsp;कपड़ा&nbsp;भिगोकर&nbsp;स्पंज&nbsp;बाथ&nbsp;(Sponge&nbsp;Bath)&nbsp;दिया&nbsp;जा&nbsp;सकता&nbsp;है।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">कमरे&nbsp;का&nbsp;तापमान:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;नहलाने&nbsp;और&nbsp;मालिश&nbsp;के&nbsp;समय&nbsp;कमरे&nbsp;की&nbsp;खिड़कियां&nbsp;बंद&nbsp;रखें&nbsp;ताकि&nbsp;सीधी&nbsp;ठंडी&nbsp;हवा&nbsp;न&nbsp;लगे।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">मालिश&nbsp;से&nbsp;गर्माहट:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;नहलाने&nbsp;से&nbsp;पूर्व&nbsp;नारियल&nbsp;या&nbsp;बादाम&nbsp;के&nbsp;गुनगुने&nbsp;तेल&nbsp;से&nbsp;हल्की&nbsp;मालिश&nbsp;करें।&nbsp;इससे&nbsp;शरीर&nbsp;में&nbsp;रक्त&nbsp;संचार&nbsp;बेहतर&nbsp;होता&nbsp;है,&nbsp;गर्माहट&nbsp;बनी&nbsp;रहती&nbsp;है&nbsp;और&nbsp;हड्डियां&nbsp;मजबूत&nbsp;होती&nbsp;हैं।</span></li></ul><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">3.&nbsp;त्वचा&nbsp;की&nbsp;नमी&nbsp;का&nbsp;रखें&nbsp;खास&nbsp;ख्याल&nbsp;(Moisturization)</span></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">शुष्क&nbsp;और&nbsp;ठंडी&nbsp;हवाओं&nbsp;के&nbsp;कारण&nbsp;शिशुओं&nbsp;की&nbsp;नाजुक&nbsp;त्वचा&nbsp;में&nbsp;रूखापन&nbsp;आ&nbsp;जाता&nbsp;है।&nbsp;स्पंज&nbsp;या&nbsp;स्नान&nbsp;के&nbsp;तुरंत&nbsp;बाद&nbsp;शिशु-सुरक्षित&nbsp;मॉइस्चराइजर&nbsp;या&nbsp;बेबी&nbsp;लोशन&nbsp;लगाना&nbsp;चाहिए,&nbsp;जिससे&nbsp;त्वचा&nbsp;की&nbsp;प्राकृतिक&nbsp;नमी&nbsp;लॉक&nbsp;हो&nbsp;सके।</span></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">4.&nbsp;स्तनपान:&nbsp;संक्रमण&nbsp;से&nbsp;बचाव&nbsp;का&nbsp;प्राकृतिक&nbsp;सुरक्षा&nbsp;कवच</span></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">6&nbsp;माह&nbsp;से&nbsp;कम&nbsp;उम्र&nbsp;के&nbsp;शिशुओं&nbsp;के&nbsp;लिए&nbsp;मां&nbsp;का&nbsp;दूध&nbsp;(Breastfeeding)&nbsp;सबसे&nbsp;उत्तम&nbsp;आहार&nbsp;है।&nbsp;इसमें&nbsp;मौजूद&nbsp;एंटीबॉडीज&nbsp;बच्चे&nbsp;को&nbsp;मौसमी&nbsp;संक्रमणों&nbsp;और&nbsp;वायरस&nbsp;से&nbsp;लड़ने&nbsp;की&nbsp;ताकत&nbsp;देते&nbsp;हैं।&nbsp;सर्दियों&nbsp;में&nbsp;बच्चे&nbsp;को&nbsp;नियमित&nbsp;अंतराल&nbsp;पर&nbsp;दूध&nbsp;पिलाते&nbsp;रहें&nbsp;ताकि&nbsp;उसका&nbsp;हाइड्रेशन&nbsp;स्तर&nbsp;बना&nbsp;रहे।</span></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">5.&nbsp;कमरे&nbsp;का&nbsp;वातावरण&nbsp;और&nbsp;हीटर&nbsp;का&nbsp;सही&nbsp;चयन</span></h3><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">ऑयल&nbsp;हीटर&nbsp;है&nbsp;बेहतर&nbsp;विकल्प:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;कमरे&nbsp;को&nbsp;गर्म&nbsp;रखने&nbsp;के&nbsp;लिए&nbsp;ऑयल&nbsp;हीटर&nbsp;का&nbsp;उपयोग&nbsp;सबसे&nbsp;सुरक्षित&nbsp;माना&nbsp;जाता&nbsp;है,&nbsp;क्योंकि&nbsp;यह&nbsp;हवा&nbsp;की&nbsp;नमी&nbsp;को&nbsp;नहीं&nbsp;सुखाता।&nbsp;साधारण&nbsp;हीटर&nbsp;हवा&nbsp;को&nbsp;शुष्क&nbsp;बना&nbsp;देते&nbsp;हैं,&nbsp;जिससे&nbsp;सांस&nbsp;की&nbsp;नली&nbsp;और&nbsp;त्वचा&nbsp;में&nbsp;जलन&nbsp;हो&nbsp;सकती&nbsp;है।&nbsp;साधारण&nbsp;हीटर&nbsp;के&nbsp;साथ&nbsp;ह्यूमिडिफायर&nbsp;(Humidifier)&nbsp;या&nbsp;पानी&nbsp;का&nbsp;बर्तन&nbsp;जरूर&nbsp;रखें।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">खतरनाक&nbsp;धुआं:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;बंद&nbsp;कमरे&nbsp;में&nbsp;कभी&nbsp;भी&nbsp;कोयला,&nbsp;कंडा&nbsp;या&nbsp;लकड़ी&nbsp;की&nbsp;अंगीठी&nbsp;न&nbsp;जलाएं।&nbsp;इससे&nbsp;निकलने&nbsp;वाली&nbsp;कार्बन&nbsp;मोनोऑक्साइड&nbsp;गैस&nbsp;नवजात&nbsp;के&nbsp;लिए&nbsp;जानलेवा&nbsp;साबित&nbsp;हो&nbsp;सकती&nbsp;है।</span></li></ul><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">6.&nbsp;सुबह&nbsp;की&nbsp;हल्की&nbsp;धूप&nbsp;से&nbsp;पाएं&nbsp;विटामिन-डी</span></h3><p><span style="background-color: inherit; color: rgb(31, 31, 31);">सुबह&nbsp;8&nbsp;से&nbsp;10&nbsp;बजे&nbsp;के&nbsp;बीच&nbsp;की&nbsp;गुनगुनी&nbsp;धूप&nbsp;में&nbsp;शिशु&nbsp;को&nbsp;10&nbsp;से&nbsp;15&nbsp;मिनट&nbsp;ले&nbsp;जाना&nbsp;लाभकारी&nbsp;होता&nbsp;है।&nbsp;इससे&nbsp;प्राकृतिक&nbsp;विटामिन-डी&nbsp;मिलता&nbsp;है&nbsp;और&nbsp;शरीर&nbsp;को&nbsp;स्वाभाविक&nbsp;गर्माहट&nbsp;मिलती&nbsp;है।&nbsp;ध्यान&nbsp;रहे&nbsp;कि&nbsp;सीधी&nbsp;धूप&nbsp;सीधे&nbsp;बच्चे&nbsp;की&nbsp;आंखों&nbsp;पर&nbsp;न&nbsp;पड़े।</span></p><h3><span style="background-color: inherit; color: rgb(31, 31, 31);">7.&nbsp;संक्रमण&nbsp;और&nbsp;बाहरी&nbsp;संपर्कों&nbsp;से&nbsp;बचाव</span></h3><ul><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">हाथों&nbsp;की&nbsp;स्वच्छता:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;बच्चे&nbsp;को&nbsp;गोद&nbsp;में&nbsp;लेने&nbsp;या&nbsp;छूने&nbsp;से&nbsp;पहले&nbsp;हाथों&nbsp;को&nbsp;साबुन&nbsp;या&nbsp;सैनिटाइजर&nbsp;से&nbsp;अच्छी&nbsp;तरह&nbsp;साफ&nbsp;करें।</span></li><li><strong style="background-color: inherit; color: rgb(31, 31, 31);">बीमार&nbsp;व्यक्तियों&nbsp;से&nbsp;दूरी:</strong><span style="background-color: inherit; color: rgb(31, 31, 31);">&nbsp;यदि&nbsp;परिवार&nbsp;में&nbsp;किसी&nbsp;सदस्य&nbsp;को&nbsp;सर्दी,&nbsp;खांसी&nbsp;या&nbsp;फ्लू&nbsp;के&nbsp;लक्षण&nbsp;हों,&nbsp;तो&nbsp;उन्हें&nbsp;नवजात&nbsp;से&nbsp;दूर&nbsp;रखें।&nbsp;साथ&nbsp;ही,&nbsp;इस&nbsp;मौसम&nbsp;में&nbsp;शिशु&nbsp;को&nbsp;भीड़भाड़&nbsp;वाले&nbsp;सार्वजनिक&nbsp;स्थानों&nbsp;पर&nbsp;ले&nbsp;जाने&nbsp;से&nbsp;बचें।</span></li></ul><p></p>',
