) VALUES (
  'RhiogVgM8UFNBTyxuL7F',
  'RhiogVgM8UFNBTyxuL7F-yxuL7F',
  'झारखंड में ग्रामीण क्षेत्रों में आजीविका मिशन से जुड़े कैडर कर्मियों ने अपने मानदेय में बढ़ोतरी की मांग',
  'झारखंड&nbsp;में&nbsp;ग्रामीण&nbsp;क्षेत्रों&nbsp;में&nbsp;आजीविका&nbsp;मिशन&nbsp;से&nbsp;जुड़े&nbsp;कैडर&nbsp;कर्मियों&nbsp;ने&nbsp;अपने&nbsp;मानदेय&nbsp;में&nbsp;बढ़ोतरी&nbsp;की&nbsp;मांग&nbsp;तेज&nb...',
  '<p>झारखंड&nbsp;में&nbsp;ग्रामीण&nbsp;क्षेत्रों&nbsp;में&nbsp;आजीविका&nbsp;मिशन&nbsp;से&nbsp;जुड़े&nbsp;कैडर&nbsp;कर्मियों&nbsp;ने&nbsp;अपने&nbsp;मानदेय&nbsp;में&nbsp;बढ़ोतरी&nbsp;की&nbsp;मांग&nbsp;तेज&nbsp;कर&nbsp;दी&nbsp;है।&nbsp;झारखंड&nbsp;राज्य&nbsp;आजीविका&nbsp;ऑल&nbsp;कैडर&nbsp;संघ&nbsp;ने&nbsp;सरकार&nbsp;के&nbsp;सामने&nbsp;कई&nbsp;मांगें&nbsp;रखी&nbsp;हैं।&nbsp;संघ&nbsp;का&nbsp;कहना&nbsp;है&nbsp;कि&nbsp;कैडर&nbsp;कर्मी&nbsp;ग्रामीण&nbsp;महिलाओं&nbsp;को&nbsp;सरकारी&nbsp;योजनाओं&nbsp;से&nbsp;जोड़ने,&nbsp;कृषि,&nbsp;पशुपालन,&nbsp;बैंकिंग,&nbsp;बीमा&nbsp;और&nbsp;आजीविका&nbsp;से&nbsp;जुड़े&nbsp;कई&nbsp;महत्वपूर्ण&nbsp;कार्य&nbsp;करते&nbsp;हैं,&nbsp;लेकिन&nbsp;उनके&nbsp;वर्तमान&nbsp;मानदेय&nbsp;से&nbsp;परिवार&nbsp;चलाना&nbsp;मुश्किल&nbsp;हो&nbsp;रहा&nbsp;है।&nbsp;हाल&nbsp;ही&nbsp;में&nbsp;साहिबगंज&nbsp;में&nbsp;भी&nbsp;आजीविका&nbsp;ऑल&nbsp;कैडर&nbsp;की&nbsp;महिलाओं&nbsp;ने&nbsp;मानदेय&nbsp;बढ़ोतरी&nbsp;और&nbsp;नियमित&nbsp;भुगतान&nbsp;की&nbsp;मांग&nbsp;को&nbsp;लेकर&nbsp;ज्ञापन&nbsp;और&nbsp;प्रदर्शन&nbsp;किया।संघ&nbsp;की&nbsp;ओर&nbsp;से&nbsp;जारी&nbsp;पत्र&nbsp;में&nbsp;बताया&nbsp;गया&nbsp;है&nbsp;कि&nbsp;आजीविका&nbsp;ऑल&nbsp;कैडर&nbsp;ग्रामीण&nbsp;क्षेत्रों&nbsp;में&nbsp;स्वयं&nbsp;सहायता&nbsp;समूहों&nbsp;की&nbsp;महिलाओं&nbsp;को&nbsp;प्रशिक्षण&nbsp;देने&nbsp;और&nbsp;उन्हें&nbsp;रोजगार&nbsp;एवं&nbsp;स्वरोजगार&nbsp;से&nbsp;जोड़ने&nbsp;का&nbsp;काम&nbsp;करते&nbsp;हैं।&nbsp;इनके&nbsp;कार्यों&nbsp;में&nbsp;कृषि,&nbsp;पशुपालन,&nbsp;बागवानी,&nbsp;बैंकिंग,&nbsp;बीमा,&nbsp;कौशल&nbsp;विकास,&nbsp;सरकारी&nbsp;योजनाओं&nbsp;का&nbsp;लाभ&nbsp;दिलाना&nbsp;और&nbsp;MIS&nbsp;में&nbsp;डाटा&nbsp;एंट्री&nbsp;जैसे&nbsp;काम&nbsp;शामिल&nbsp;हैं।</p><p>पत्र&nbsp;में&nbsp;अलग-अलग&nbsp;स्तर&nbsp;के&nbsp;कैडर&nbsp;का&nbsp;भी&nbsp;उल्लेख&nbsp;किया&nbsp;गया&nbsp;है।&nbsp;प्रखंड&nbsp;स्तर&nbsp;पर&nbsp;BRP-LH&nbsp;और&nbsp;ASK/GRC&nbsp;Co-Ordinator,&nbsp;जबकि&nbsp;संकुल&nbsp;स्तर&nbsp;पर&nbsp;GCRP,&nbsp;बैंक&nbsp;सखी,&nbsp;FLCRP,&nbsp;BDSP/CRP-EP,&nbsp;नवजीवन&nbsp;सखी,&nbsp;सेतु&nbsp;दीदी&nbsp;और&nbsp;JRP&nbsp;जैसे&nbsp;कैडर&nbsp;शामिल&nbsp;हैं।&nbsp;वहीं&nbsp;SHG&nbsp;और&nbsp;VO&nbsp;स्तर&nbsp;पर&nbsp;सक्रिय&nbsp;महिला,&nbsp;आजीविका&nbsp;कृषक&nbsp;सखी,&nbsp;आजीविका&nbsp;पशु&nbsp;सखी&nbsp;और&nbsp;बागवानी&nbsp;सखी&nbsp;जैसी&nbsp;जिम्मेदारियां&nbsp;भी&nbsp;निभाई&nbsp;जाती&nbsp;हैं।संघ&nbsp;का&nbsp;कहना&nbsp;है&nbsp;कि&nbsp;BRP-LH&nbsp;जैसे&nbsp;कैडर&nbsp;को&nbsp;पशुपालन,&nbsp;कृषि,&nbsp;प्राकृतिक&nbsp;खेती,&nbsp;जैविक&nbsp;खाद,&nbsp;बागवानी,&nbsp;उत्पादक&nbsp;समूह,&nbsp;लखपति&nbsp;महिला&nbsp;किसान&nbsp;और&nbsp;विभिन्न&nbsp;सरकारी&nbsp;योजनाओं&nbsp;से&nbsp;जुड़े&nbsp;कार्य&nbsp;करने&nbsp;होते&nbsp;हैं।&nbsp;इसके&nbsp;अलावा&nbsp;समूह&nbsp;की&nbsp;महिलाओं&nbsp;को&nbsp;योजनाओं&nbsp;का&nbsp;लाभ&nbsp;दिलाने&nbsp;और&nbsp;आजीविका&nbsp;रजिस्टर&nbsp;तैयार&nbsp;करने&nbsp;जैसे&nbsp;काम&nbsp;भी&nbsp;किए&nbsp;जाते&nbsp;हैं।</p><p>संघ&nbsp;ने&nbsp;पत्र&nbsp;में&nbsp;बताया&nbsp;है&nbsp;कि&nbsp;वर्तमान&nbsp;भुगतान&nbsp;उनके&nbsp;अनुसार&nbsp;पर्याप्त&nbsp;नहीं&nbsp;है&nbsp;और&nbsp;भुगतान&nbsp;में&nbsp;देरी&nbsp;की&nbsp;समस्या&nbsp;भी&nbsp;सामने&nbsp;आती&nbsp;है।&nbsp;इसी&nbsp;वजह&nbsp;से&nbsp;मानदेय&nbsp;बढ़ाने&nbsp;के&nbsp;साथ-साथ&nbsp;समय&nbsp;पर&nbsp;भुगतान&nbsp;की&nbsp;मांग&nbsp;की&nbsp;गई&nbsp;है।अब&nbsp;बात&nbsp;करते&nbsp;हैं&nbsp;संघ&nbsp;की&nbsp;प्रमुख&nbsp;मांगों&nbsp;की।</p><p>संघ&nbsp;की&nbsp;मांग&nbsp;है&nbsp;कि&nbsp;BRP-LH&nbsp;का&nbsp;मानदेय&nbsp;बढ़ाकर&nbsp;प्रति&nbsp;माह&nbsp;20&nbsp;हजार&nbsp;800&nbsp;रुपये&nbsp;किया&nbsp;जाए।&nbsp;इसके&nbsp;अलावा&nbsp;कम्युनिकेशन,&nbsp;यात्रा&nbsp;भत्ता,&nbsp;स्टेशनरी,&nbsp;पेट्रोल&nbsp;और&nbsp;मोबाइल&nbsp;रिचार्ज&nbsp;के&nbsp;लिए&nbsp;3&nbsp;हजार&nbsp;रुपये&nbsp;प्रतिमाह&nbsp;देने&nbsp;की&nbsp;मांग&nbsp;रखी&nbsp;गई&nbsp;है।</p><p>साथ&nbsp;ही&nbsp;सभी&nbsp;BRP-LH&nbsp;को&nbsp;FTAM&nbsp;में&nbsp;शामिल&nbsp;कर&nbsp;HR&nbsp;पॉलिसी&nbsp;के&nbsp;तहत&nbsp;सुविधाएं&nbsp;देने,&nbsp;भविष्य&nbsp;निधि&nbsp;यानी&nbsp;PF&nbsp;का&nbsp;लाभ&nbsp;देने&nbsp;और&nbsp;मानदेय&nbsp;का&nbsp;भुगतान&nbsp;सीधे&nbsp;व्यक्तिगत&nbsp;बैंक&nbsp;खाते&nbsp;में&nbsp;हर&nbsp;महीने&nbsp;करने&nbsp;की&nbsp;मांग&nbsp;की&nbsp;गई&nbsp;है।संघ&nbsp;ने&nbsp;हर&nbsp;वर्ष&nbsp;मानदेय&nbsp;में&nbsp;10&nbsp;से&nbsp;15&nbsp;प्रतिशत&nbsp;बढ़ोतरी&nbsp;का&nbsp;प्रावधान&nbsp;करने&nbsp;की&nbsp;मांग&nbsp;भी&nbsp;रखी&nbsp;है।&nbsp;इसके&nbsp;अलावा&nbsp;JSLPS&nbsp;की&nbsp;विभिन्न&nbsp;भर्तियों&nbsp;में&nbsp;कैडर&nbsp;कर्मियों&nbsp;के&nbsp;लिए&nbsp;60&nbsp;प्रतिशत&nbsp;आरक्षण,&nbsp;बीमा&nbsp;सुरक्षा&nbsp;और&nbsp;अन्य&nbsp;सुविधाएं&nbsp;देने&nbsp;की&nbsp;मांग&nbsp;की&nbsp;गई&nbsp;है।</p><p>वहीं&nbsp;25&nbsp;अगस्त&nbsp;2026&nbsp;को&nbsp;साहिबगंज&nbsp;में&nbsp;जेएसएलपीएस&nbsp;की&nbsp;दीदियों&nbsp;ने&nbsp;मानदेय&nbsp;बढ़ोतरी,&nbsp;नियमित&nbsp;भुगतान&nbsp;और&nbsp;विभिन्न&nbsp;भत्तों&nbsp;की&nbsp;मांग&nbsp;को&nbsp;लेकर&nbsp;प्रदर्शन&nbsp;किया।&nbsp;प्रदर्शन&nbsp;के&nbsp;बाद&nbsp;डीपीएम&nbsp;को&nbsp;ज्ञापन&nbsp;सौंपा&nbsp;गया।&nbsp;रिपोर्ट&nbsp;के&nbsp;अनुसार,&nbsp;प्रदर्शनकारियों&nbsp;ने&nbsp;प्रखंड&nbsp;और&nbsp;संकुल&nbsp;स्तर&nbsp;के&nbsp;अलग-अलग&nbsp;कैडर&nbsp;के&nbsp;लिए&nbsp;संशोधित&nbsp;मानदेय&nbsp;की&nbsp;मांग&nbsp;भी&nbsp;रखी।</p>',
