) VALUES (
  '0yO1bKUqwqkcAHBq9IIh',
  '0yO1bKUqwqkcAHBq9IIh-Bq9IIh',
  'गोड्डा: सुराइकिट्टा भुयांसी टोला में बारिश का कहर, मुख्य सड़क बनी तालाब',
  'गोड्डा&nbsp;|&nbsp;विशेष&nbsp;संवाददाता&nbsp;| मानसून&nbsp;की&nbsp;पहली&nbsp;फुहारें&nbsp;जहाँ&nbsp;एक&nbsp;ओर&nbsp;किसानों&nbsp;के&nbsp;चेहरे&nbsp;पर&nbsp;मुस्कान&nbsp;लाती&nbsp;हैं,&nbsp;वहीं&nbsp;ग...',
  '<p><strong>गोड्डा&nbsp;|&nbsp;विशेष&nbsp;संवाददाता&nbsp;|</strong></p><p></p><p>मानसून&nbsp;की&nbsp;पहली&nbsp;फुहारें&nbsp;जहाँ&nbsp;एक&nbsp;ओर&nbsp;किसानों&nbsp;के&nbsp;चेहरे&nbsp;पर&nbsp;मुस्कान&nbsp;लाती&nbsp;हैं,&nbsp;वहीं&nbsp;गोड्डा&nbsp;जिले&nbsp;के&nbsp;पकड़िया&nbsp;स्थित&nbsp;<strong>सुराइकिट्टा&nbsp;भुयांसी&nbsp;टोला</strong>&nbsp;के&nbsp;निवासियों&nbsp;के&nbsp;लिए&nbsp;यह&nbsp;मौसम&nbsp;&#39;आफत&#39;&nbsp;बनकर&nbsp;आता&nbsp;है।&nbsp;पिछले&nbsp;कुछ&nbsp;दिनों&nbsp;से&nbsp;हो&nbsp;रही&nbsp;निरंतर&nbsp;बारिश&nbsp;ने&nbsp;यहाँ&nbsp;की&nbsp;मुख्य&nbsp;सड़क&nbsp;को&nbsp;सड़क&nbsp;कम&nbsp;और&nbsp;एक&nbsp;विशाल&nbsp;&#39;तालाब&#39;&nbsp;में&nbsp;बदल&nbsp;दिया&nbsp;है।&nbsp;यह&nbsp;जलजमाव&nbsp;केवल&nbsp;पानी&nbsp;का&nbsp;ठहराव&nbsp;नहीं&nbsp;है,&nbsp;बल्कि&nbsp;स्थानीय&nbsp;प्रशासन&nbsp;के&nbsp;उन&nbsp;दावों&nbsp;की&nbsp;कलई&nbsp;भी&nbsp;है,&nbsp;जो&nbsp;हर&nbsp;साल&nbsp;विकास&nbsp;के&nbsp;नाम&nbsp;पर&nbsp;किए&nbsp;जाते&nbsp;हैं।</p><p></p><h3><strong>जब&nbsp;सड़क&nbsp;बन&nbsp;जाए&nbsp;&#39;जानलेवा&nbsp;जाल&#39;</strong></h3><p>तस्वीरें&nbsp;भयावह&nbsp;हैं।&nbsp;सड़क&nbsp;का&nbsp;कहीं&nbsp;अता-पता&nbsp;नहीं&nbsp;है,&nbsp;चारों&nbsp;तरफ&nbsp;गंदा&nbsp;पानी&nbsp;भरा&nbsp;हुआ&nbsp;है।&nbsp;इस&nbsp;जलजमाव&nbsp;ने&nbsp;स्थानीय&nbsp;निवासियों&nbsp;की&nbsp;दैनिक&nbsp;दिनचर्या&nbsp;को&nbsp;पूरी&nbsp;तरह&nbsp;से&nbsp;ठप&nbsp;कर&nbsp;दिया&nbsp;है।&nbsp;दोपहिया&nbsp;वाहन&nbsp;चालक&nbsp;हों&nbsp;या&nbsp;कार&nbsp;सवार,&nbsp;सभी&nbsp;के&nbsp;लिए&nbsp;यह&nbsp;रास्ता&nbsp;किसी&nbsp;&#39;डेथ&nbsp;ट्रैप&#39;&nbsp;से&nbsp;कम&nbsp;नहीं&nbsp;है।</p><p>पानी&nbsp;के&nbsp;नीचे&nbsp;छिपे&nbsp;हुए&nbsp;गहरे&nbsp;गड्ढे&nbsp;कब&nbsp;किसी&nbsp;को&nbsp;चोटिल&nbsp;कर&nbsp;दें,&nbsp;यह&nbsp;कहना&nbsp;मुश्किल&nbsp;है।&nbsp;स्थानीय&nbsp;लोगों&nbsp;की&nbsp;मानें&nbsp;तो&nbsp;आवागमन&nbsp;की&nbsp;स्थिति&nbsp;इतनी&nbsp;खराब&nbsp;हो&nbsp;चुकी&nbsp;है&nbsp;कि&nbsp;घर&nbsp;से&nbsp;बाहर&nbsp;निकलना&nbsp;भी&nbsp;एक&nbsp;बड़ी&nbsp;चुनौती&nbsp;बन&nbsp;गया&nbsp;है।&nbsp;स्कूल&nbsp;जाने&nbsp;वाले&nbsp;बच्चों&nbsp;और&nbsp;बुजुर्गों&nbsp;के&nbsp;लिए&nbsp;तो&nbsp;यह&nbsp;रास्ता&nbsp;किसी&nbsp;जंग&nbsp;जीतने&nbsp;जैसा&nbsp;है।</p><p></p><h3><strong>हर&nbsp;साल&nbsp;वही&nbsp;दर्द,&nbsp;फिर&nbsp;भी&nbsp;चुप्पी</strong></h3><p>ग्रामीणों&nbsp;का&nbsp;कहना&nbsp;है&nbsp;कि&nbsp;यह&nbsp;पहली&nbsp;बार&nbsp;नहीं&nbsp;है&nbsp;जब&nbsp;वे&nbsp;इस&nbsp;समस्या&nbsp;से&nbsp;जूझ&nbsp;रहे&nbsp;हैं।&nbsp;यह&nbsp;एक&nbsp;वार्षिक&nbsp;चक्र&nbsp;बन&nbsp;चुका&nbsp;है।&nbsp;बरसात&nbsp;आते&nbsp;ही&nbsp;सड़कें&nbsp;तालाब&nbsp;बन&nbsp;जाती&nbsp;हैं&nbsp;और&nbsp;प्रशासन&nbsp;की&nbsp;ओर&nbsp;से&nbsp;केवल&nbsp;आश्वासन&nbsp;मिलते&nbsp;हैं।&nbsp;ग्रामीणों&nbsp;में&nbsp;इस&nbsp;बात&nbsp;का&nbsp;आक्रोश&nbsp;है&nbsp;कि&nbsp;वर्षों&nbsp;से&nbsp;वे&nbsp;जल&nbsp;निकासी&nbsp;(ड्रेनेज)&nbsp;की&nbsp;मांग&nbsp;कर&nbsp;रहे&nbsp;हैं,&nbsp;लेकिन&nbsp;उनकी&nbsp;सुध&nbsp;लेने&nbsp;वाला&nbsp;कोई&nbsp;नहीं&nbsp;है।&nbsp;सवाल&nbsp;यह&nbsp;है&nbsp;कि&nbsp;आखिर&nbsp;कब&nbsp;तक&nbsp;इस&nbsp;&#39;नरकीय&nbsp;जीवन&#39;&nbsp;को&nbsp;सहने&nbsp;के&nbsp;लिए&nbsp;ग्रामीण&nbsp;मजबूर&nbsp;रहेंगे?</p><p></p><h3><strong>प्रशासन&nbsp;से&nbsp;तत्काल&nbsp;समाधान&nbsp;की&nbsp;उम्मीद</strong></h3><p>धैर्य&nbsp;का&nbsp;बांध&nbsp;अब&nbsp;टूटने&nbsp;लगा&nbsp;है।&nbsp;आक्रोशित&nbsp;ग्रामीणों&nbsp;ने&nbsp;जिला&nbsp;प्रशासन&nbsp;से&nbsp;दो&nbsp;सूत्री&nbsp;मांगें&nbsp;रखी&nbsp;हैं:</p><ul><li><strong>तात्कालिक&nbsp;राहत:</strong>&nbsp;पंप&nbsp;मशीनों&nbsp;के&nbsp;जरिए&nbsp;सड़क&nbsp;से&nbsp;पानी&nbsp;की&nbsp;निकासी&nbsp;की&nbsp;जाए&nbsp;ताकि&nbsp;आवाजाही&nbsp;शुरू&nbsp;हो&nbsp;सके।</li><li><strong>स्थायी&nbsp;समाधान:</strong>&nbsp;जल&nbsp;निकासी&nbsp;की&nbsp;एक&nbsp;सुदृढ़&nbsp;योजना&nbsp;(पक्की&nbsp;नाली)&nbsp;का&nbsp;निर्माण&nbsp;हो,&nbsp;ताकि&nbsp;आने&nbsp;वाले&nbsp;वर्षों&nbsp;में&nbsp;उन्हें&nbsp;इस&nbsp;समस्या&nbsp;का&nbsp;सामना&nbsp;न&nbsp;करना&nbsp;पड़े।</li></ul><p></p><h3><strong>क्या&nbsp;प्रशासन&nbsp;की&nbsp;नींद&nbsp;अब&nbsp;टूटेगी?</strong></h3><p>सुराइकिट्टा&nbsp;भुयांसी&nbsp;टोला&nbsp;की&nbsp;यह&nbsp;स्थिति&nbsp;स्थानीय&nbsp;प्रशासन&nbsp;की&nbsp;कार्यशैली&nbsp;पर&nbsp;एक&nbsp;बड़ा&nbsp;सवालिया&nbsp;निशान&nbsp;है।&nbsp;क्या&nbsp;प्रशासन&nbsp;तब&nbsp;तक&nbsp;इंतज़ार&nbsp;करेगा&nbsp;जब&nbsp;तक&nbsp;कि&nbsp;कोई&nbsp;बड़ा&nbsp;हादसा&nbsp;न&nbsp;हो&nbsp;जाए?&nbsp;या&nbsp;फिर&nbsp;इस&nbsp;बार&nbsp;वे&nbsp;संवेदनशीलता&nbsp;दिखाते&nbsp;हुए&nbsp;ठोस&nbsp;कदम&nbsp;उठाएंगे?</p><p>पूरी&nbsp;जनता&nbsp;की&nbsp;नजरें&nbsp;अब&nbsp;इस&nbsp;बात&nbsp;पर&nbsp;टिकी&nbsp;हैं&nbsp;कि&nbsp;सुराइकिट्टा&nbsp;भुयांसी&nbsp;टोला&nbsp;के&nbsp;लोगों&nbsp;को&nbsp;राहत&nbsp;कब&nbsp;मिलती&nbsp;है।&nbsp;फिलहाल,&nbsp;गाँव&nbsp;के&nbsp;लोग&nbsp;सिर्फ&nbsp;एक&nbsp;सुरक्षित&nbsp;सड़क&nbsp;और&nbsp;बुनियादी&nbsp;सुविधाओं&nbsp;की&nbsp;उम्मीद&nbsp;लगाए&nbsp;बैठे&nbsp;हैं।</p><p></p><blockquote><strong>[Current&nbsp;News:]</strong>&nbsp;<em>एक&nbsp;जिम्मेदार&nbsp;नागरिक&nbsp;होने&nbsp;के&nbsp;नाते,&nbsp;यदि&nbsp;आपके&nbsp;पास&nbsp;भी&nbsp;ऐसी&nbsp;कोई&nbsp;समस्या&nbsp;है,&nbsp;तो&nbsp;उसे&nbsp;साझा&nbsp;करें।&nbsp;आपका&nbsp;एक&nbsp;छोटा&nbsp;सा&nbsp;प्रयास&nbsp;प्रशासन&nbsp;को&nbsp;जगाने&nbsp;के&nbsp;लिए&nbsp;काफी&nbsp;हो&nbsp;सकता&nbsp;है।</em></blockquote>',
